    private void Start()
    {
        myCaptions.Add("Eine Geschichte des Waldes- vom Reh und der Wölfin");
        myCaptions.Add("Die Geschichte einer Liebe jenseits der Grenzen");
        myCaptions.Add("Die Geschichte der Bergleute");
        myCaptions.Add("Die Geschichte der dunklen Königin");
        myCaptions.Add("Die Geschichte vom jungen Herzog");
        myCaptions.Add("Die Geschichte von der letzten Elfe und dem letzten Erdwichtel");
        myCaptions.Add("Die Geschichte der stillen Hüter");
        myCaptions.Add("Geschichte des Mannes, der über das Licht wachte");
        myCaptions.Add("Die Geschichte des letzten Eids von Kareth");
        myCaptions.Add("Die Geschichte von zwei Schwestern");
        myCaptions.Add("Eine Geschichte des Waldes -Die Sage vom Alten Grün");
        myCaptions.Add("Eine Geschichte von Freundschaft jenseits der Zeit");
        myCaptions.Add("Dashuri- Tales from the Magic Forest Teil 1");
        myCaptions.Add("Dashuri- Tales from the Magic Forest Teil 2");
        myCaptions.Add("Dashuri- Tales from the Magic Forest Teil 3");
        myCaptions.Add("Dashuri- Tales from the Magic Forest Teil 4");

        myTexts.Add("Lange bevor Straßen das Land durchschnitten und bevor die Menschen lernten, jedem Baum einen Namen zu geben, gab es einen Wald, der wie ein Lebewesen atmete. Seine Wurzeln reichten tief in die Erde hinein, seine Wipfel flüsterten die Geheimnisse der Welt, und seine Geschöpfe lebten nach Gesetzen die älter waren, undkostbarer, als alle Kronen oder Münzen der Menschen.In diesem Wald lebte eine Hirschkuh, schlank und graubraun, flink wie die Furcht und sanft wie der Morgennebel. Sie war in einem harten Frühling geboren worden, als der Frost zu lange verweilte und viele Kitze niemals auf die Beine kamen. Sie überlebte nurdank eines anderen Wesens. Dieses andere Wesen war eine Wölfin. Es geschah nahe der Flussbiegung, wo der Waldboden tief abfiel und das Schilf dicht wuchs. Das Kitz war kaum mehr als ein zitterndes Bündel aus Beinen und Atem, gefangen im steigenden Wasser, nachdem die Schneeschmelze die Ufer des Flusses gesprengt hatte. Seine Mutter war in Panik geraten, kreiste, rief – und verschwand dann, als der Geruchvon Raubtieren ihre Nase erreichte.Die Wölfin war nicht gekommen um zu jagen, sondern um zu trinken.\r\nGeschichten des Windes für Projekt.odt\r\nSie war damals jung, kaum ausgewachsen; ihr eigenes Rudel war vor Kurzem durch Hunger und Konflikte zerstreut worden. Sie hatte gelernt, allein zu überleben, die Zähne scharf, die Rippen sichtbar, die Augen ständig suchend. Als sie den Schrei hörte, dünn und verzweifelt, ließ etwas in ihr sie innehalten.Ein junges Rehkind war dabei zu ertrinken.Die Wölfin watete hinein in Wasser. Kälte biss in ihre Beine, durchtränkte ihr Fell, aber sie drängte vorwärts und packte das Kitz im Nacken mit einer Sanftheit, die sie einem Beutetier gegenüber nie zuvor gezeigt hatte. Sie schleppte den kleinen Körper ans Ufer und stand darüber, schwer atmend, hin- und hergerissen zwischen Instinkt und etwas, für das sie keine Worte hatte.Das Kitz lebte.Die Mutter der Hirschkuh kehrte in der Dämmerung zurück, vom Terror gezeichnet undmit wilden Augen, und fand ihr Kind lebend vor. Sie erspähte die Wölfin, die in der Nähe stand, bereit zur Flucht oder zum verzweifelten Kampf um ihr Kind. Für einen langen Moment hielt der Wald den Atem an.Dann neigte die Mutter ihr Haupt – nicht in Unterwerfung, sondern in Anerkennung. Die Wölfin wich zurück und verschwand zwischen den Bäumen, wobei sie eine Erinnerung mit sich trug, die sie niemals verstehen, aber auch niemals vergessen würde.Der Wind raschelte in den Zweigen, als die Wölfin in die Schatten des Waldes eintauchte.Jahre vergingen.Aus dem Kitz wuchs die Hirschkuh heran und wurde stark und trittsicher. Sie lernte alles über jeden verborgenen Pfad, jede sichere Mulde, jedes Warnsignal der Jahreszeiten. Sie brachte eigene Kitze zur Welt und lehrte sie, wann sie rennen, wann sie erstarren und wann sie der Stille des Waldes vertrauen mussten.Die Wölfin wurde in dieser Zeit zu einer Anführerin.Sie scharte Streuner um sich – hungrige Einzelgänger, verwundete Weibchen, Welpen, die ihre Mütter verloren hatten. Sie lehrte sie, ohne Verschwendung zu jagen, ohne Grausamkeit zu töten und dem Wald Opfergaben darzubringen, indem sie das Gleichgewicht hielten. Unter ihrer Herrschaft überlebte das Rudel Winter, an denen dieWölfe eigentlich hätten zerbrechen müssen.Keine von beiden erinnerte sich klar an die andere. Die Zeit lässt selbst die schärfsten Momente verschwimmen. Doch etwas blieb zurück – ein Band. Ein ungesprochener Faden, geknüpft aus Atem und Wasser und Barmherzigkeit.Und der Wind trug ihn geduldig mit sich. Ein Winter kam, härter als alle zuvor. Schnee fiel früh und schwer, begrub die Nahrung, brachte Flüsse zum Verstummen und trieb den Hunger tief in die Knochen. Die Wölfe wurden verzweifelt. Selbst unter der Zurückhaltung der Wölfin rückte das Rudel näher an die Wildpfade heran, als sie es jemals zuvor gewagt hatte.Das war der Zeitpunkt, an dem die Jäger eintrafen.\r\nGeschichten des Windes für Projekt.odt\r\nMänner mit Eisenfallen, nach Feuer riechenden Stöcken und Stimmen, die zu laut für den Wald waren. Sie kamen wegen der Wölfe, aber es war ihnen gleichgültig, was sie sonst noch töteten.Eines Morgens führte die Hirschkuh – nun älter, ihre Schritte langsamer, aber weise geworden über die Jahre – ihre Kitze über eine Lichtung, die sie schon tausendmal überquert hatte.Die Falle war unter dem Schnee verborgen.Metall schnappte zu. Knochen brachen. Der Schrei riss den Wald entzwei.Die Hirschkuh kämpfte, trat um sich, blutete – aber Eisen beugt sich weder der Furcht noch der Kraft der Verzweiflung. Bei Einbruch der Dunkelheit heulten Wölfe in der Ferne, und die Hirschkuh ahnte, dass sie keine weitere Morgendämmerung sehen würde.Ihre Kitze versteckten sich und sahen hilflos zu.Ein eiskalter Wind wehte.Die Wölfin erreichte die Lichtung zuerst.Sie roch Blut, Eisen und noch etwas anderes – etwas unbeschreiblich Vertrautes. Sie sah die Hirschkuh gefangen, schwächer werdend, die Augen noch immer stolz, aber bereits trüb. Das Rudel sammelte sich hinter ihr, angespannt, hungrig, unsicher.Dies war leichte Beute. Dies war Überleben. Dies war Gleichgewicht.Und doch.Die Wölfin trat allein vor. Sie umkreiste die Hirschkuh, während sich Erinnerungen regten wie halb vergessene Träume von kaltem Wasser und einem geretteten Leben. Eine Erinnerung daran, wie ein geschenktes Leben ihr einst Trost geboten hatte über ihren Verlust und ihre Einsamkeit. Sie hörte das leise Wimmern der versteckten Kitze und fühlte, wie etwas in ihrer Brust aufbrach.Sie griff die Falle an.Metall biss in ihre Zähne, schnitt in ihr Zahnfleisch, aber sie riss mit einer unerreichtenWut daran. Das Rudel schloss sich ihr an – nicht um zu töten, sondern um zu befreien.Gemeinsam bogen sie Eisen, brachen Pfähle und sprengten Ketten.Die Hirschkuh brach zusammen, befreit, aber im Sterben liegend. Die Stimmen der Jäger hallten in der Nähe wider.Die Wölfin traf eine Entscheidung.Sie stellte sich zwischen die Hirschkuh und die herannahenden Männer und heulte – keine Drohung, sondern ein Befehl. Ihr Rudel schwärmte aus, lockte die Jäger weg und führte sie tief in den Wald, wo sich die Pfade wanden und der Schnee jedes Geräusch verschlang.Sie kehrten im Morgengrauen zurück, verwundet, aber lebendig.Die Hirschkuh lebte nicht mehr. Doch ihre Kitze taten es.Sie standen am Rand der Lichtung, zitternd, und sahen zu, wie die Wölfe zurückkehrten. Die Wölfin traf ihren Blick und näherte sich nicht. Sie senkte einmal ihr Haupt, dann wandte sie sich ab.Der Wald war wieder still.Jahre später war die Wölfin alt.\r\nGeschichten des Windes für Projekt.odt\r\nIhre Schnauze war grau geworden, ihre Schritte langsam. Eines Frühlings legte sie sichunter eine uralte Eiche und erhob sich nicht mehr. Ihr Rudel betrauerte sie zuerst mit lautem Geheul, und dann in tiefer Stille, wie Wölfe es tun, und zog weiter. Im selben Frühling führte eine junge Hirschkuh ihre Herde sicher an einer vertrauten Flussbiegung vorbei. Sie hielt inne, die Ohren zuckten, und sie schnupperte in der Luft – als würde sie etwas erkennen, das längst vergangen war. Der Wind strich durch die Bäume, sanft und wissend. Vielleicht war es Zufall, dass die Nachkommen der Hirschkuh immer an diese Stelle kamen um zu trinken. Vielleicht war es Instinkt. Vielleicht aber auch erinnert sich der Wald besser an Freundlichkeit als an Grausamkeit. Die Wahrheit kennt nur der Wind.");
        myTexts.Add("Es gab eine Zeit, in der die Welt bereits geteilt war, wenn auch noch nicht durch Mauern oder Kriege. Sie war im Stillen geteilt – durch Furcht, durch Vergessen und durch das langsame Verblassen des Glaubens und der Erinnerung an die Magie.Auf der einen Seite der Grenze lagen die Lande der Menschen, wo Felder vermessen und bedeutsame Namen niedergeschrieben wurden und wo alles seinen Platz und eineZweck hatte. Auf der anderen Seite lag das, was von der alten Welt übrig geblieben war: Wälder, in denen sich die Pfade bewegten, wenn niemand hinsah; Flüsse, die sich an Lieder erinnerten; und Wesen, deren Existenz nicht von Gesetzen abhing, sondern von Geschichten.Zwischen diesen Landen erstreckte sich eine weite Wiese. Niemand beanspruchte sie. Niemand bewachte sie. Und so blieb sie frei.Dort begegneten sie einander.Der Junge kam zuerst dorthin. Er sollte eigentlich nicht so weit umherwandern. Sein Dorf lag einen Tagesmarsch entfernt, und seine Eltern glaubten, dass Grenzen Kinder sicher hielten. Aber der Junge war dem Wind stets bereiter gefolgt als den Regeln. Er mochte es, wie der Wind an seinem Haar zupfte, wie er Düfte von fernen Orten herantrug und von unsichtbaren Dingen flüsterte.\r\nGeschichten des Windes für Projekt.odt\r\nEines Nachmittags, als er einem selbst gefalteten Papiervogel nachjagte, überquerte er die Grenze zur Wiese. Und dort, im hohen Gras sitzend, war ein Kind, das er noch nie zuvor gesehen hatte.Sie sah fast aus wie er – und doch ganz und gar nicht. Ihre Ohren waren leicht gespitzt. Ihre Augen spiegelten den Himmel einen Augenblick länger wider, als sie es sollten. Wenn sie lächelte, lehnten sich die Blumen zu ihr, als würden sie zuhören.Sie starrten einander schweigend an. Dann lachten sie. Sie wurden Freunde, ohne es beim Namen zu nennen.Sie trafen sich am nächsten Tag wieder. Und am nächsten. Immer auf der Wiese, immer genau dort, wo sich keine der beiden Welten ganz real anfühlte. Sie teilten Brot und Beeren, Geschichten und Fragen. Sie bauten kleine Figuren aus Lehm und Garn und taten so, als wären sie die Hüter der Wiese.Der Junge erzählte von seinem Dorf, von der Schule und der Arbeit und davon, wie die Erwachsenen endlos über Dinge stritten, die niemals wichtig schienen. Das Mädchen sprach von Waldversammlungen, von Geistern, die in der Dämmerung tanzten, und von Liedern, die zerbrochene Rinde und gebrochene Herzen gleichermaßen zu heilen vermochten.Sie fragten nicht, warum sie anders waren. Für Kinder ist Andersartigkeit nur interessant, niemals seltsam.Doch Grenzen bleiben nicht ewig weich.Der Junge kam nicht mehr. Tage vergingen. Dann Wochen. Die Wiese wurde unruhig. Der Wind kreiste suchend umher.Als der Junge schließlich zurückkehrte, war er verändert. Älter. Stiller. Sein Lachen zögerte, als hätte es Vorsicht gelernt. Er erzählte ihr, dass seine Familie fortzog, dass nun Soldaten die Straßen bewachten und dass seine Eltern sagten, es sei gefährlich umherzustreifen. Er wusste nicht, warum nur er den Pfad zu dieser Wiese finden konnte. Aber nie war ihm jemand hierher gefolgt. Obwohl er oft darüber nachgedacht hatte, diesenwunderbaren Ort mit anderen zu teilen. Doch er tat es nie.„Sie sagen, deinesgleichen sei nicht echt“, sagte er und starrte ins Gras. „Sie sagen, an dich zu glauben, sei kindisch.“Das Mädchen weinte nicht. Aber die Blumen um sie herum schlossen ihre Blütenblätter.„Sie sagen, dein Volk hätte uns vergessen“, antwortete sie leise. „Sie sagen, die Tür schließt sich.“Ihre Hände hielten einander an diesem Tag lange fest, und keiner von beiden wusste, wie man Lebewohl sagt. Also blieben sie sitzen. Als ob sie spürten, dass wenn sie nun los ließen, dies ein Abschied für immer sein würde.Ein Sturm zog in jener Nacht auf, plötzlich und heftig. Als der Morgen graute, war die Wiese gezeichnet, die Pfade ausgelöscht. Die Grenze verhärtete sich. Und die Kinder wurden zurück in ihre eigenen Welten gezogen, wie Blätter in getrennte Strömungen.Jahre vergingen.Der Junge wurde ein Mann. Er erlernte ein Handwerk, lernte Zurückhaltung, lernte, dasStaunen hinter Zweckmäßigkeit zu verbergen. Er heiratete, zog Kinder groß, erzählte ihnen Geschichten – aber niemals diese Geschichten. Irgendwann auf dem Weg überzeugte er sich selbst davon, dass die Wiese ein Traum gewesen war.\r\nGeschichten des Windes für Projekt.odt\r\nDas Mädchen wuchs ebenfalls – aber anders. Die Zeit biegt sich seltsam für jene, die an Magie gebunden sind. Sie sah zu, wie die Wälder lichter wurden, die Geister verblassten, die Lieder verstummten. Sie wartete an der Wiese, lange nachdem diese aufgehört hatte, sich wie ein Treffpunkt anzufühlen, und stattdessen begonnen hatte, mehr wie ein Grab zu erscheinen.Und doch vergaß sie niemals sein Gesicht. Der Wind erinnerte sich für sie beide. Selbster vermisste die Präsenz des letzten Menschen an diesem besonderen Ort, der ihm noch hatte zuhören können.In einem Herbst, als die Welt sich dünner anfühlte als gewöhnlich, überquerte der Mann die Wiese erneut. Er wusste nicht, warum, oder wie es möglich war. Seine Füße trugen ihn einfach dorthin. Vielleicht war es die Trauer – seine Frau war im Winter zuvor verstorben. Vielleicht war es die Erschöpfung von einem Leben, das er vorsichtig, behutsam und korrekt gelebt hatte.Oder vielleicht war es die Liebe, unvollendet und unvergessen.Sie war da. Älter, ja – aber unverkennbar.Sie erkannten einander sofort, nicht durch den Anblick, sondern durch die Art wie der Wind zwischen ihnen hindurchrauschte, atemlos und begierig.Diesmal sprachen sie als Erwachsene miteinander. Von Verlust. Von Reue. Von dem stillen Schmerz, nur die Hälfte des Lebens gelebt zu haben, das sich ihre Herzen einst erträumt hatten.„Ich dachte, du seist nicht echt“, gestand er. „Ich dachte, du wärst eine Geschichte, die ich mir selbst erzählt habe.“Sie lächelte traurig. „Ich war echt“, sagte sie. „Aber Geschichten brauchen den Glauben, um zu überleben.“Sie küssten sich – einmal, sanft, als hätten sie Angst, die Welt könnte zerbrechen, wenn sie mehr wagten.Und dann wurde der Wind still.Die Entscheidung wurde niemals laut ausgesprochen. Er konnte nicht bleiben. Sein Körper gehörte einer Welt ohne Magie. Seine Kinder brauchten ihn. Seine Zeit war gemessen, endlich. Sie konnte nicht gehen. Der Wald brauchte Zeugen. Die alten Lieder mussten bewahrt werden. Wenn sie ganz in seine Welt hinüberwechselte, würden sie verblassen.Also liebten sie einander über die Grenze hinweg.Sie trafen sich, wann immer der Tag es zuließ – manchmal lagen Wochen dazwischen, manchmal Jahre. Und doch erschien es jedesmal, als wäre nur ein Augenblick vergangen seit der letzten Zweisamkeit. Sie alterten in unterschiedlichem Tempo. Ihre Hände veränderten sich, ihre Stimmen wurden tiefer und weicher. Aber ihre Liebe bliebseltsam unberührt, bewahrt in dem Raum zwischen den Welten.Als der Mann ein Greis geworden war, kam er ein letztes Mal. Er lag im Gras der Wiese,sein Atem war flach, seine Augen gütig.„Glaubst du“, fragte er, „dass diese Liebe von Bedeutung war?“Sie kniete neben ihm und drückte ihre Stirn gegen seine. „Sie war von Bedeutung“, sagte sie. „Sie hat mich verändert. Und sie hat dich verändert. Das ist genug.“Als er seinen letzten Atemzug tat, erhob sich der Wind – nicht in Trauer, sondern in Ehrfurcht – und trug ihn sanft in den Wald hinein.\r\nGeschichten des Windes für Projekt.odt\r\nLange nachdem beide Welten ihre Namen vergessen hatten, sprachen die Menschen von einer Wiese, auf der selbst im Winter Blumen blühten und wo sich die Luft immer warm anfühlte, wie erfüllt von Erinnerungen an Freundschaft und Liebe.Manche sagten, es sei ein Ort der Magie. Manche sagten, es sei nur eine schöne Geschichte. Aber Liebende, die Grenzen überschritten – Grenzen des Landes, des Glaubens, der Furcht – spürten manchmal, wie der Wind um sie herum innehielt.Als würde er sich erinnern. Als würde er lächeln. Selbst über die größte Distanz hinwegschenkte seitdem dieses Überschreiten der Grenzen, das zwei Liebende gewagt hatten, auch allen anderen Liebenden dieses Gefühl. Dass es einen Ort gab, an dem ihre Liebe eine Platz hatte. Und auch wenn sie nicht wussten warum, so beflügelte dies doch ihren Mut.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Das Dorf lag in einem schmalen Tal, eingepresst zwischen den Bergen wie ein Geheimnis, das die Welt zu bewahren beschlossen hatte. Seine Bewohner waren weder für Reichtum noch für Macht bekannt, sondern für ihre Beständigkeit. Der Stein war ihr Gefährte, ihr Feind und ihr Lebensunterhalt.Tief unter dem Dorf verliefen die alten Stollen.Sie waren gegraben worden, lange bevor Dinge einen Namen hatten – weitergegrabenwurde zuerst von Händen, die von der Not geleitet wurden, später von Händen, die dem Befehl gehorchten. Schicht um Schicht, Gang um Gang; einige gestützt durch Holz und Sorgfalt, andere nur zusammengehalten durch Gewohnheit und Hoffnung.Und weit unten, tiefer als die meisten Dorfbewohner zu denken wagten, arbeiteten dieBergleute.Oder, wie manche sie nannten: die Gebundenen.Als die Erde das erste Mal stöhnte, klang es wie ein ferner Sturm. Staub fiel von den Balken. Lampen erzitterten. Die Bergleute erstarrten und lauschten. Sie kannten die\r\nGeschichten des Windes für Projekt.odt\r\nSprache des Steins besser als jeder andere. Dies war keine kleine Warnung. Dies war der Berg, der sein Gewicht verlagerte.Dann zerbrach die Welt.Wände barsten. Stützen schrien. Ein Donnern rollte durch die Tunnel, als der Haupteingang in sich zusammenbrach und die Unterwelt vom Himmel darüber abschnitt. Dunkelheit verschlang jedes Geräusch. Männer wurden zu Boden geworfen, unter Trümmern begraben, von herabstürzendem Fels zermalmt.Als das Beben aufhörte, folgte die Stille – schwer und endgültig.Jene, die noch atmeten, zählten einander durch ihre Stimmen. Sie waren weniger als zuvor.Über der Erde schrie und betete das Dorf. Staub stieg aus der Erde auf wie ein Totenschleier. Der Eingang zur Mine war verschwunden, begraben unter Tonnen von Stein. Die Menschen an der Oberfläche gruben, bis ihre Hände bluteten. Sie lauschten nach Stimmen, die niemals antworteten.Bei Einbruch der Dunkelheit sprachen die Ältesten die Worte aus, die niemand hören wollte. „Es gibt keine Luft mehr.“ „Es gibt kein Durchkommen.“ „Sie sind verloren.“Kerzen wurden entzündet. Namen wurden geflüstert. Das Dorf trauerte. Und der Wind trug ihren Kummer davon.Unten lebten die Bergleute. Noch. Sie fanden Lufteinschlüsse, eng und zerbrechlich, die durch Spalten atmeten, welche leise von der Welt darüber wisperten. Sie teilten sich ihre Lampen ein, ihre Nahrung, ihre Kraft.Und langsam begriffen sie die Wahrheit. Der Einsturz hatte sie nicht nur eingeschlossen. Er hatte den Berg über dem Dorf gespalten. Wenn der Druck sich erneut verlagerte – wenn die Hohlräume nach oben hin einbrachen – würden Häuser, Straßen und Menschen im Ganzen verschlungen werden. Die Tunnel hielten den Berg an seinem Platz. Und wenn sie, die im Untergrund Eingesperrten, nach draußen durchbrächen... würde das Dorf sterben.Einige wollten dennoch einen Ausweg graben. Nicht aus Selbstsucht – sondern aus Angst, aus Liebe zu ihren Familien, aus der einfachen menschlichen Weigerung heraus, sich hinzulegen und einfach widerstandsloszu verschwinden. Doch andere sahen den Stein mit anderen Augen. Es warendie ältesten, erfahrensten Arbeiter unter ihnen. Die Stillen. Jene, die gelernt hatten , auf den Berg zu hören, anstatt gegen ihn zu kämpfen.„Wenn wir den Weg öffnen“, sagte einer von ihnen mit heiserer Stimme, „werden wir den Himmel mit uns in die Tiefe reißen.“ Stille folgte.Dann sprach ein anderer – ein Mann, dessen Handgelenke noch immer die Male des Eisens trugen. „Es war uns nie bestimmt, ein langes Leben zu führen“, sagte er. „Aber vielleicht können wir anderen ein langes Leben schenken.“In diesem Moment erst wurden sie an die Wahrheit erinnert, ungesprochen, aber von allen verstanden. Sie waren keine freien Männer. Die meisten Bergleute waren Sklaven. Verschleppt aus fernen Ländern, in Ketten gekauft oder hineingeboren. Unter die Erde geschickt, weil es dem Stein egal ist, wer auf ihn blutet. Aufseher und Wachenhatten an jenem Tag an ihrer Seite gearbeitet – in geringerer Zahl, bewaffnet, gewohntan den Gehorsam ihrer Untergebenen.Nun, zum ersten Mal, erkannte der Stein keinen Rang an. Zum ersten Mal gab es eine Wahl.\r\nGeschichten des Windes für Projekt.odt\r\nDie Wachen versuchten, sie zu befehligen. „Grabt!“, schrien sie. „Macht den Eingang frei. Das ist ein Befehl!“ Doch die Sklaven rührten sich nicht. Stattdessen blickten sie einander an – in Gesichter, die von jahrelanger Arbeit gezeichnet waren, auf Hände, die durch Arbeit ruiniert worden waren, die niemals ihnen selber zugute kam, auf Leben, die damit verbracht wurden, sich sagen zu lassen, ihr Wert sei geringer als die Luft zum Atmen.Und in der Dunkelheit spürten sie, wie die Luft entwich. Ein Sklave trat vor. Dann noch einer. Sie griffen nicht an. Sie flohen nicht. Sie hielten die Wachenfest. Nicht mit Gewalt, sondern mit Standhaftigkeit. „Ihr werdet jetzt zuhören“, sagten sie. „Oder wir alle sterben als ein Nichts.“Die Wachen wehrten sich zunächst, und erhoben ihre Waffen. Dann hielten sie inne. Denn Mut, wahrer Mut, wiegt schwerer als jedes Schwert und jede Rüstung. Gemeinsam schmiedeten sie einen Plan.Sie würden sich nicht nach draußen graben. Sie würden die eingestürzten Tunneln nicht freiräumen, sondern verstärken. Steine wurden bewegt. Lücken wurden gefüllt. Schwachstellen wurden mit den letzten Holzvorräten gestützt. Sie arbeiteten nicht nach außen, sondern nach innen – sie opferten Raum, versiegelten sich Schicht um Schicht selbst, um den Berg davon abzuhalten, über ihnen einzustürzen.Mit jeder Wand, die sie schlossen, wurde die Luft dünner. Mit jeder Stütze, die sie setzten, wurde das Dorf sicherer. Irgendwo oben schliefen Kinder friedlich durch die Nacht.In der letzten Kammer konnten sie nichts mehr sehen. Sie arbeiteten durch Berührung,durch Erfahrung, durch Vertrauen. Durch einen schmalen Riss im Fels glaubten sie Gras zu riechen. Frische Luft. Morgen. Sie schlossen die Augen und stellten sich die Welt über ihnen vor.Jemand lachte leise. Jemand weinte. Niemand versuchte, den Riss zu erreichen. Sie wollten ihr Bild nicht zerstören. Sie saßen zusammen – Sklaven und Wachen, endlich ebenbürtig. „Es tut mir leid“, flüsterte einer der Aufseher mit brechender Stimme. „Ich hatte nicht euren Mut.“ Hände, die einst Fesseln getragen hatten, waren nun frei. Sie legten sich tröstend auf seine Schultern.Der Wind schlüpfte durch den Stein, unvorstellbar sanft, und strich über ihre Gesichter,während ihr Atem flacher wurde. In diesem letzten Augenblick gehörten sie niemandem mehr. Sie waren frei.Über der Erde hielt der Berg stand. Das Dorf überlebte.Jahre später begannen die Veränderungen – langsam, unsicher, fast unmerklich. Antreiber wurden mitleidiger. Ketten verschwanden. Die Menschen sprachen von einer Tragödie, die Bergleute und Wachen gleichermaßen begraben hatte, ein gemeinsames Schicksal, eine Mahnung an die Grausamkeit des Berges.Geschichtsbücher sollten sehr viel später behaupten den Moment zu kennen, in dem die Herzen begannen, sich zu wandeln. In dem die Menschen Barmherzigkeit erlernten. Dass Gleichheit aus dem Kummer erwuchs.Doch sie irrten sich. Die Wahrheit lag tiefer. Begraben unter Stein, Entschlossenheit und Opferbereitschaft.Doch kein Geschichtsbuch würde jemals davon erzählen.\r\nGeschichten des Windes für Projekt.odt\r\nDie Wahrheit kennt nur der Wind.");
        myTexts.Add("Es gab einst eine Königin, deren Schönheit so strahlend war, dass sie wie ein Leuchtfeuer in einer dunklen Welt wirkte. Doch Schönheit ist oft nur eine Maske, ein dünner Schleier über einem Abgrund. Der Wind, der durch die kalten Korridore ihres Schlosses wehte, wusste schon lange vor den Menschen, dass ihr Herz aus Scherben bestand – scharfkantig, zerbrochen und unmöglich zu heilen.Die Geschichte begann mit einem König, dessen Herz nach dem Tod seiner geliebten Gemahlin in tiefer Trauer versunken war. In seiner Einsamkeit suchte er nach Trost undfand eine Frau, deren Herkunft so geheimnisvoll war wie ihr unergründliches Wesen, und ihr Äußeres. Er fragte nicht, aus welchen fernen Landen sie stammte oder welche Narben ihre Seele trug. Er sah nur ihre Anmut und glaubte, in der Rettung dieser Frau eine eigene Erlösung zu finden. Er nahm sie zur Frau und krönte sie zur Königin, in der Hoffnung, dass Liebe das Dunkel in ihrem Inneren vertreiben würde. Denn ihre Haut war weiß wie Eis, aber ihr Herz schien schwarz zu sein.Doch er irrte sich. Die Königin trug den Hass nicht als Laune, sondern als Erbe. Ihre eigene Familie hatte ihr Dinge angetan, die so unsagbar waren, dass sie jeden Glauben an die Güte verloren hatte. Für sie war die Welt ein Ort der Beobachter – Menschen, die zugesehen hatten wie sie zerbrach, ohne jemals einzugreifen. Ihr Hass war ein langsames Gift, geboren aus tiefem Leid. Sie wollte die Welt dafür bestrafen, dass sie scheinbar unberührt existierte, während die Gequälte selbst innerlich bereits gestorben war.\r\nGeschichten des Windes für Projekt.odt\r\nDer König, ein gütiger Mann, konnte gegen die Kälte in ihrem Inneren nicht ankämpfen. Er welkte dahin, verzehrt von der Traurigkeit über eine Ehe, die nur aus Schweigen und Frost bestand, bis er schließlich starb. Er hinterließ nur einen Sohn, einen Prinzen, dessen Herz so sanft war wie das seines Vaters.Nach dem Tod des Königs wurde die Trauer des Volkes bald von Furcht abgelöst. Die dunkle Königin regierte mit eiserner Hand. Doch ihren schlimmsten Zorn reservierte sie für den Jungen. Er erinnerte sie an alles, was sie verabscheute: Unschuld, Sanftmutund die Hoffnung, dass Liebe ausreichte, um zu überleben. Jeden Tag fand sie neue Wege, ihn zu quälen. Es waren nicht nur Schläge; es war die psychische Zerstörung, das ständige Herabsetzen seiner Existenz.Der Prinz ertrug die Strafen ohne Gegenwehr. Er sah sie nicht als Feindin, sondern als ein verwundetes Tier, das nur wusste, wie man biss. In seinem Herzen brannte ein Licht, das ihr Hass nicht auslöschen konnte. Er beobachtete, wie sein Land unter ihrer Herrschaft litt, wie die Steuern stiegen und das Lachen aus den Straßen verschwand. Die Königin genoss das Leid der anderen; es war die einzige Sprache, die sie noch verstand.Dann kam ein Winter, der kälter und gnadenloser war als alle zuvor. Die Ernten waren mager gewesen, und die Vorräte der Bauern reichten kaum bis zum nächsten Mondwechsel. Doch anstatt die Speicher zu öffnen, plante die Königin, das restliche Getreide für sich selbst zu behalten und prunkvolle Geschenke an ihre Verbündeten in fernen Landen zu schicken, um ihre Macht zu festigen. Sie wollte das Volk verhungern lassen, um ihren eigenen Status zu erhöhen. „Familien sind Ungeziefer“, pflegte sie zu sagen. „Sie säen nur Schwäche. Man muss sie vernichten, um Platz für etwas Neues zuschaffen.“Das Schloss war auf hohen Klippen erbaut, umgeben von massiven Mauern und Soldaten, die jeden Befehl der Königin ohne Zögern ausführten. Sie fühlte sich sicher in ihrem Elfenbeinturm, hoch über dem Elend der „einfachen Bauern“, die sie verächtlich als Ratten bezeichnete.An jenem schicksalhaften Abend trat sie auf den großen Balkon, der über den Abgrundragte. Der Wind peitschte ihr entgegen, doch sie genoss die Kälte. Da trat der Prinz aus dem Schatten. Zum ersten Mal wich er nicht zurück. Er konfrontierte sie und flehtesie an, ihre Entscheidung zu ändern, dem Volk Brot zu geben und nicht den Tod über das Land zu bringen.Die Königin lachte nur. Es war ein hohles, hässliches Geräusch. Sie beschimpfte ihn, nannte ihn schwach wie seinen Vater und schlug ihn ins Gesicht, immer und immer wieder. Sie verhöhnte seine Tränen und seine Sorge um die Menschen. In diesem Moment geschah etwas im Inneren des Prinzen. Es war kein Hass, der ihn trieb, sondern die Erkenntnis, dass Gerechtigkeit manchmal eine schreckliche Form annehmen muss.Er stieß sie von sich weg – ein einziger, kraftvoller Stoß. Die Königin taumelte, ihre Absätze fanden keinen Halt auf dem eisglatten Stein, und sie stürzte über das Geländer in die Tiefe.In diesem Moment, als der feste Boden unter ihren Füßen verschwand, geschah das Unmögliche. Während sie fiel und der kalte Wind gegen ihr Gesicht presste, geschah etwas mit ihrer Seele. In der Schwerelosigkeit des Todes lösten sich die Schichten aus\r\nGeschichten des Windes für Projekt.odt\r\nSchmerz und Bosheit ab. Der Hass, den sie wie eine Rüstung getragen hatte, zersprang beim Aufprall gegen die Luft.Tränen, die sie seit ihrer Kindheit nicht mehr vergossen hatte, rollten über ihre Wangenund wurden vom Wind davongetragen. In ihren letzten Sekunden sah sie nicht die Feinde, die sie bestrafen wollte, sondern die kleinen Momente der Schönheit, die sie sich selbst verwehrt hatte. Reue überflutete sie wie eine warme Welle. Sie sah das Gesicht des Prinzen vor ihrem geistigen Auge und flüsterte mit ihrem letzten Atemzug Worte in den tosenden Wind, die niemand jemals für möglich gehalten hätte:„Ich vergebe dir... und es tut mir leid.“Zum ersten Mal in ihrem Leben fühlte sie keine Bosheit mehr. Nur Frieden.Als man ihren Körper am Fuße der Klippen fand, glaubte jeder an einen tragischen Unfall. Der Prinz war von den Schlägen gezeichnet, seine Wunden waren frisch, und niemand hätte ihm jemals zugetraut, die Hand gegen die Königin zu erheben.Er wurde zum König gekrönt, und unter seiner Herrschaft blühte das Land wieder auf.Die Geschichtsbücher schrieben später, dass die bösartige Königin bis zu ihrem letztenAtemzug das Volk verflucht habe. Man erzählte sich, dass sie mit einem Schrei des Zorns gestorben sei und dass ihr schwarzes Herz niemals Liebe gekannt habe. Die Menschen hassten ihr Andenken, und ihr Name wurde zu einem Synonym für Grausamkeit.Niemand ahnte, dass sie als eine andere Frau gestorben war, als sie gelebt hatte. Niemand hörte ihr Verzeihen. Niemand sah ihre Tränen der Reue. Die Welt behielt ihr Bild der „bösen Königin“ bei, denn Menschen brauchen Monster, um sich selbst gut zu fühlen.Niemand würde jemals erfahren, was wirklich geschehen war beim Fall der dunklen Königin.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Es gab einst eine Herzogsfamilie, die über einen kleinen Teil des Landes herrschte. Sie war reich, und jedes Familienmitglied besaß eine eigene Residenz und eine Schar von Dienern; sie lebten besser, als die meisten Menschen es sich jemals zu träumen wagten. Doch der alte Herzog starb und hinterließ den Thron der Familie seinem Sohn.Da dieser noch nicht mündig war, sollte er von seinem Onkel aufgezogen und\r\nGeschichten des Windes für Projekt.odt\r\nbeschützt werden, bis er alt genug wäre, um seinen rechtmäßigen Platz einzunehmen. Der Sohn war ein fröhlicher und freundlicher Junge, der jeden um sich herum zum Lächeln brachte. Und jedes Lächeln war aufrichtig – außer das seines Onkels. Denn dieser begehrte den Thron heimlich für sich selbst und träumte davon, eines Tages seine eigenen Söhne über das Land herrschen zu sehen. Doch da er ein so bösartiger Mann war, hatte ihn seine Frau verlassen, noch bevor sie ihm Kinder schenken konnte.Der junge Herzog liebte es, das Land zu erkunden und sich mit Adligen wie Bauern gleichermaßen anzufreunden. Der Onkel ließ ihn gewähren, in der Hoffnung, dem Jungen würde etwas zustoßen und er würde sterben. Doch niemand wollte dem Kind ein Leid zufügen. Im Gegenteil, jeder gab auf ihn Acht.Eines schicksalhaften Tages begegnete der Junge dem Sohn eines Bauern, der ein wenig abseits der Dörfer lebte, die er sonst besuchte. Der Junge hätte sein Zwilling sein können! Sie beschlossen, dies geheim zu halten und füreinander Brüder zu sein. Zuerst betrat der junge Herzog das Dorf des Bauernsohnes nie, um nicht von den Dorfbewohnern gesehen zu werden. Doch bald wurde er neugierig. So beschlossen sie,für eine Woche die Plätze zu tauschen. Sie bereiteten alles vor. Da sie sich praktisch alles über ihr jeweiliges Leben erzählt hatten, gab es kaum noch Geheimnisse. Es bliebnur noch, einander das Nötigste beizubringen. Der junge Herzog lehrte seinen Freund Lesen, Schreiben, die Etikette und andere Dinge, die ein Herzog wissen musste; und der Bauernjunge lehrte den kleinen Herzog, wie man die Felder pflügt, das Wetter liestund wie man das Vieh versorgt.Dann tauschten sie die Plätze.Beide waren voller Vorfreude. Für den kleinen Bauernjungen wurde ein Traum wahr; zum ersten Mal in seinem Leben musste er seinen Körper nicht arbeiten lassen, bis er umfiel. Dennoch konnte er nicht an sich halten und half beim Fegen des Stalls oder beim Abräumen nach dem Abendessen. Doch das Personal lächelte nur und wunderte sich nicht – war der kleine Herzog nicht schon immer ein herzensguter Junge gewesen? Der echte junge Herzog erkundete derweil das Dorf, arbeitete unter der brennenden Sonne und im strömenden Regen und liebte schon nach wenigen Tagen die Familie des Bauern und ihr Heim, als wäre es sein eigenes. Niemals in seinem Leben war er glücklicher gewesen.An dem Tag, an dem sie sich wieder treffen wollten, beobachtete der junge Herzog, wie sein Onkel zusammen mit seinem Freund, dem Bauernjungen, zur Jagd in die Sümpfe ritt. Er folgte ihnen heimlich, um unbemerkt die Plätze zurückzutauschen. Doch was er sah, sollte ihn für den Rest seines Lebens schmerzen. Der Onkel blickte sich um, und als er sich allein wähnte, stieß er den kleinen Bauernjungen in eine tiefe Stelle des Sumpfes.Als das Kind aufschrie und flehend seine Hand ausstreckte, stieß ihn der Onkel mit seinem Stiefel tiefer in den Schlamm. Der wahre junge Herzog schrie auf, doch es war zu spät und er war zu weit entfernt, um gehört zu werden. Der Wind rüttelte laut in den Zweigen der Bäume und trug seineStimme nicht hinüber.\r\nGeschichten des Windes für Projekt.odt\r\nMit gebrochenem Herzen wandte er sich ab. Er dachte an die Familie seines Freundes und daran, wie sein eigener Onkel fähig gewesen war, scheinbar sein eigenes Fleisch und Blut zu töten. Und der junge Herzog entschied, dass die Familie seines Freundes ihren Sohn nicht verlieren sollte, so wie seine eigene Familie gerade den kleinen Herzog verloren hatte.So lebte er das Leben des Bauernjungen weiter und sah die Mitglieder seiner wahren Familie viele Jahre lang nicht wieder. Die Nachricht vom Tod eines jungen Adligen und die Trauer der herzoglichen Familie verbreiteten sich im ganzen Land. Doch nach einer Weile wurde es vergessen, und das Leben im kleinen Dorf ging weiter.Bis eines Tages, viele Jahre später, eine Stimme in seinem Herzen den einstigen jungen Herzog – der nun ein erwachsener Mann war – zurück in den Sumpf rief. Er stand da und schwieg, als ob er auf etwas wartete, während er seines Freund gedachte. Jedes Jahr, wenn er die Gelegenheit fand, brachte er Blumen an die Stelle im Sumpf, an der sein Freund gestorben war, und versprach ihm, dass er nicht vergessen würde. Er versprach es jedes Mal, wenn er das Feld pflügte, jedes Mal, wenner die Tiere fütterte, und jedes Mal, wenn er die Umarmung der Mutter seines Freundesspürte.In diesen Momenten ließ er einen Teil des kleinen Bauernjungen, der einen so ungerechten Verrat erlitten hatte, in sich weiterleben, während er die glücklichen Erinnerungen an ihre gemeinsame Kindheit im Herzen trug. Der Onkel war seit jenem düsteren Tag vor vielen Jahren der Gegend ferngeblieben, die die Heimat des Bauernjungen war. Er saß nun auf dem Thron, so wie er es immer begehrt hatte. Doch seine nagenden Schuldgefühle hatten ihn schnell altern lassen und seinen Körper ausgezehrt. Da er nicht nur ein junges Leben – dazu sein eigenes Fleisch und Blut – genommen, sondern auch das Vertrauen seines Bruders und seiner ganzen Familie verraten hatte, ohne es jemals jemandem sagen zu können, war er zu einem hinfälligen, kranken alten Mann geworden. Zum ersten mal seit er sein Gewissen belastet und diese schlimme Tat vollbracht hatte, war der Onkel zum Ort seines Verbrechens zurück gekehrt. Es war genau der Tag im Jahr, an dem der Junge damals in den Tiefen des Sumpfes versunken war. Nicht wissend, dass es noch jemand anderen gab, der diesen Tag nie vergessen hatte, und der jedes Jahr zur gleichen Zeit an diesen Ort zurück kehrte. Der Onkel starrte auf den Sumpf. Er wunderte sich über das Blumenbeet, das genau hier wuchs, während sonst nirgendwo in der Nähe etwas blühte – als der junge Herzog aus dem Gebüsch trat. Der Onkel starrte ihn mit weit aufgerissenen Augen an. Dann heulte er auf, als hätte ereinen Geist gesehen, schrie um Vergebung und rannte in seiner Angst und Verwirrung tief in den Sumpf hinein. Er wurde nie wieder gesehen.Der junge Herzog kehrte auf seinen Bauernhof zurück und erfuhr später, dass eine Tante von ihm den Thron übernommen und geheiratet hatte, um die Linie der Familie\r\nGeschichten des Windes für Projekt.odt\r\nfortzuführen. Der Onkel hingegen starb ganz allein, undentdeckt, in Angst und Qual. Niemand würde jemals hiervon erfahren.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Es kam eine Zeit, wie es immer wieder passiert im Kreislauf des Lebens der Welt, in der die Magie nicht mit einem Schlag verschwand. Aber sie wurde dünner. Ihre Kraft verblasste, wie die Kraft eines Atems der an jedem Morgen weniger Nebel auf dem Glas hinterlässt, bis es eines Tages gar nicht mehr beschlägt. Bis niemand mehr, der auf der anderen Seite vorbeigeht, sehen kann, dass dort jemand lebt.Die Menschen bemerkten es zuerst nicht. Sie bemerkten stattdessen den Fortschritt. Stein ersetzte Holz. Das Feuer wurde gezähmt. Worte wurden aufgeschrieben und nicht länger nur gesungen und erzählt. Die Welt wurde lauter, heller, schneller – und irgendwie leerer. Und langsam, fast sanft... vergaßen die Menschen.Tief im Wald von Shpresa stand die Große Goldene Eiche. Einst hatten ihre Blätter wie der Sonnenaufgang geleuchtet, und ihre Wurzeln hatten die Magie wie Blut durch Adern in die Welt getragen. Nun war ihre Rinde dunkel geworden, ihr Leuchten nur noch ein schwacher, müder Puls. Dennoch schlug ihr Herz. Denn irgendwo auf der Weltglaubte ein Kind noch immer. Dieser Glaube – zerbrechlich, eigensinnig, wunderschön – war genug.Und so lebten zwei letzte, kleine magische Wesen noch immer.\r\nGeschichten des Windes für Projekt.odt\r\nDie letzte Elfe war nicht größer als der Unterarm eines Kindes. Sie schimmerte matt, ihre Flügel waren durchscheinend wie der Morgentau, ihr Lachen so sanft wie Glockenspiel, das man aus weiter Ferne hört. Einst war sie durch Städte und Wälder gleichermaßen getanzt. Jetzt verließ sie die Zweige der Eiche nur noch selten.Der letzte Erdwichtel – klein, rund und mit Moos bekleidet – lebte zwischen den Wurzeln. Seine Hände waren immer warm, immer von Erde gezeichnet. Er erinnerte sich an das Gefühl der Berge, bevor sie von den Menschen Namen erhalten hatten.Sie waren die beiden Letzten ihrer Art. Nicht, weil die anderen in einer Schlacht gefallen waren – sondern weil die Welt sich nicht mehr an sie erinnerte.Das Kind, das noch an die Magie in der Welt glaubte, lag weit entfernt in seinem Bett. Sie war in einen Schlaf gefallen, als sie noch klein war – ihr Atem ruhig, ihr Gesicht friedvoll, ihre Hände gekrümmt, als hielten sie einen unsichtbaren Traum fest. Etwas war geschehen. Niemand war sich einig darüber, was es war. Manche machten eine Krankheit verantwortlich. Manche einen Fluch. Manche machten sich gar keine Gedanken darüber, was die Ursache war.Es war der Herr der Träume. Er sah, was andere nicht sehen konnten. Er hatte das Potenzial gesehen. Und so trug er das Kind in sein Reich, wo die Zeit nicht nagte und der Schlaf nicht verrottete. Er hüllte sie in Träume, weit und leuchtend – Träume von fliegenden Städten, von geheilten Welten, von Menschen, die Hand in Hand und ohne Furcht wanderten.„Sie darf nicht aufwachen“, sagte er sanft. „Noch nicht. Wenn sie es tut, wird die Magiesterben.“ Und so schlief das Kind. Und das Herz der Eiche schlug weiter.Die Welt außerhalb des Reichs der Träume, und jenseits des Waldes der Großen Goldenen Eiche, veränderte sich. Generationen kamen und gingen. Imperien stritten darüber, ob die Wahrheit in Zahlen oder in Göttern lag. Magie wurde zu einem Wort, das nur noch von Kindern benutzt wurde – und dann nichteinmal mehr von ihnen. Nun verließen die Elfe und der Erdwichtel nachts die Eiche. Sie traten in die Träume ein.Sie besuchten die Träume des Kindes als Gefährten. Manchmal war sie eine Königin, die vor einer gespaltenen Welt stand. Manchmal eine Wanderin, die Wunden mit ihren Händen heilte. Manchmal war sie einfach sie selbst – lachend, gütig, Fragen stellend, die die Sterne innehalten ließen.„Sie träumt so groß“, flüsterte der Erdwichtel einmal, während er beobachtete, wie sie mit nichts weiter als Worten eine Brücke zwischen zwei verfeindeten Ländern baute. „Das hat sie schon immer getan“, antwortete die Elfe leise.Sie bewachten ihre Träume Äonen lang. Und noch länger. Doch die Eiche wurde schwächer. Jedes Jahr schlug ihr Herz langsamer. Das Leuchten der Elfe verblasste. DieSchritte des Erdwichtels wurden schwer. Die Magie kehrte nicht zurück. Die Welt war zu voll von Gewissheit geworden, um Raum für das Staunen zu lassen.Eines Tages drehte sich der Wind. Er trug Not mit sich. Verzweiflung. Die Welt erbebte – nicht durch Erdbeben, sondern durch eine Spaltung, die so scharf war, dass sie in dieunsichtbaren Wurzeln der Realität selbst schnitt.\r\nGeschichten des Windes für Projekt.odt\r\nDie Elfe lehnte ihre Stirn gegen die Rinde der Eiche. „Es ist Zeit“, flüsterte sie. Der Erdwichtel zitterte. „Sollten wir das wirklich tun?“, fragte er. „Wenn wir sie wecken... wird keine Magie mehr übrig sein. Nicht für uns. Für niemanden.“Die Elfe kniete sich neben ihn. „Wofür ist Magie gut“, fragte sie sanft, „wenn nicht dazu, der Welt Hoffnung zu schenken? Um sie mit Leben zu füllen?“ Sie legte ihre Hand auf die Eiche. „Wenn dies unser Schicksal ist“, fuhr sie fort, die Stimme trotz der Angst fest, „dann müssen wir es annehmen.“Sie lauschten. Nicht mit den Ohren – sondern mit ihren Herzen. Und die Eiche antwortete.Sie traten in den tiefsten Traum. Der Herr der Träume sah sie kommen, Trauer lag bereits in seinen Augen. „Ihr wisst, was das kosten wird“, sagte er. „Wir wissen es“, sagte die Elfe. „Und ihr werdet nicht darum bitten, dass man sich an euch erinnert“, fügte er hinzu. Der Erdwichtel schüttelte den Kopf. „Nur, dass sie erwacht.“Sie berührten den Traum des Kindes. Und ließen los.Die Magie entwirrte sich – nicht gewaltsam, sondern liebevoll. Wie ein letztes Lied, dasin die Knochen der Welt gesungen wurde. Das Herz der Eiche flammte ein einziges Malauf, brillant und golden, und sandte seinen letzten Puls durch jede Wurzel und jeden Stein. Eine einzige goldene Träne aus Harz fiel herab, mit der die Große Goldene Eiche sich in LIebe und Trauer von der Welt verabschiedete.Das Kind regte sich. Sie erwachte.Das Mädchen erwachte in eine veränderte Welt. Sie lebte. Sie wandelte unter den Menschen. Sie sprach Worte, die Fraktionen vereinten, welche sich für Feinde gehaltenhatten. Sie erinnerte die Wissenschaft an das Staunen, und sie erinnerte den Glauben an die Güte. Sie erinnerte alle, die fanatisch an Idealen, Wissen, Gesetzen und Glauben festhielten daran, dass genügend Platz war in einem Geist, um beides einzulassen. Neues Wissen und Erkenntnisse zuzulassen, und dennoch Raum zu behalten für das wenige Ungewisse und Erstaunliche, das noch in der Welt enthalten war.Sie nannte es nicht Magie.Sie nannte es Hoffnung.Als sie starb – alt, zufrieden und nach einem erfüllten Leben – fühlte sich die Welt stiller an. Und unter der großen Eiche lagen zwei kleine Gestalten reglos da. Eine Tulpewuchs dort, wo die Elfe ruhte. Ein Vergissmeinnicht dort, wo der Erdwichtel schlief.In einem späteren Zeitalter sprachen die Menschen davon, dass die Magie an jenem Tag verschwunden sei. Die Leute sagen, niemand habe es verhindern können. Niemand weiß von zwei kleinen Händepaaren auf alter Rinde und von einer Entscheidung, die ohne sterbliche Zeugen getroffen wurde.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Wenn die Menschen von den großen Zeitaltern von Dashuri sprechen, dann sprechen sie von Königen und Generälen, von Priestern und Magiern, von Schlachten, die Grenzen verschoben, und von Wundern, die Tore zwischen den Welten öffneten.Nur selten sprechen sie von Druiden und Barden.Und wenn sie es tun, dann meist mit einem Lächeln – gütig, aber herablassend. Geschichtenerzähler. Waldvolk. Träumer.Der Wind weiß es besser.Als die Welt zum ersten Mal heilte – als die Magie noch frei durch Wurzeln und Flüsse floss – waren es nicht die Mächtigen, die alles zusammenhielten. Es waren die Stillen.Die Druiden herrschten nicht. Sie hörten zu. Sie lernten den Rhythmus der Jahreszeiten, die Sprache des Bodens, den Kummer zu früh gefällter Bäume und das Leid der Flüsse, die in steinerne Betten gezwungen wurden. Sie spürten es, wenn das Gleichgewicht kippte – nicht mit technischen Instrumenten, sondern tief in ihren Knochen. Dies gab ihnen mehr Voraussicht und mehr Macht über ihr Schicksal als jedem Herrscher.Die Barden befahlen nicht. Sie erinnerten sich. Sie webten Geschichte in Melodien, Warnungen in Reime, Hoffnung in Schlaflieder, die sie Kindern sangen, welche noch nicht wussten, wie zerbrechlich die Welt in Wahrheit war. Ihre Lieder wurden niemals aufgeschrieben, denn Geschriebenes kann verbrannt werden. Lieder, die vom Atem getragen werden, sind gleichermaßen flüchtig wie unzerstörbar. Und ihre Wirkung ist stärker als jeder Befehl.Als die ersten Risse auftauchten – anfangs klein, kaum wahrnehmbar – waren es die Druiden, die den Schmerz spürten. Die Magie wurde dünner. Die Wurzeln wurden unruhig. Die Geister zogen sich zurück. Die Druiden warnten die Räte der Regierungen. Sie sprachen zu Königen und Priestern gleichermaßen. „Etwas stimmt nicht“, sagten sie. „Die Welt vergisst sich selbst.“Man dankte ihnen. Dann ignorierte man sie.Es waren die Barden, denen es als nächstes auffiel. Die Lieder begannen, klanglos zu werden. Alte Melodien verloren ihre Macht. Kinder vergaßen Verse, von denen ihre Großeltern schworen, dass sie sie einst perfekt gesungen hatten.Also änderten die Barden ihre Lieder. Nicht offensichtlich. Sie verbargen die Wahrheit im Humor, Prophezeiungen in Liebesliedern, Erinnerungen in Tavernenweisen, die die Menschen summten, ohne jemals zu begreifen, warum sie sich dadurch getröstet und geborgen fühlten.Als der Konflikt schließlich ausbrach – als Magie und Glaube wie Feinde gegeneinanderausgespielt wurden –, so wählten die Druiden oder die Barden nicht eine „Seite“. Sie wählten schlicht die Menschen.Druiden führten Flüchtlinge durch Wälder, die sich verschoben, um die Aufgenommenen zu beschützen. Sie schufen Pfade, wo keine existierten, und verschlossen Wege vor jenen, die Unheil bringen wollten. Barden trugen Botschaften durch Kriegsgebiete, getarnt als Narren und Gaukler. Sie verbreiteten Hoffnung, wo Verzweiflung den Widerstand beendet hätte, und säten Zweifel dort, wo blinder Fanatismus die Herzen zu verhärten drohte.\r\nGeschichten des Windes für Projekt.odt\r\nSie beanspruchten niemals Ruhm für sich. Sie blieben niemals lange genug, dass ihre Gesichter und Namen in Erinnerung blieben.Wohl aber ihre Botschaft.Als sich das Tor zwischen den Welten schließlich öffnete – an jenem unmöglichen Ort im Herzen der Wüste –, so hieß es, Priester, Magier und Krieger hätten hätten Mut gezeigt und Opfer gebracht, um dieses Wunder zu ermöglichen. Das war wahr. Aber eswar unvollständig.Denn lange vor diesem Moment hatten die Druiden das Land vorbereitet und langsam die Orte geheilt, an denen Magie noch Wurzeln schlagen konnte. Und die Barden hatten die Idee der Einheit lange genug am Leben erhalten, damit überhaupt noch jemand daran glaubte, dass sie möglich sei. Ohne sie hätte sich das Tor ins Nichts geöffnet.Später, als die Welt erneut zu vergessen begann, geschah es im Stillen. Geschichten wurden nicht mehr erzählt. Lieder wurden durch Lärm ersetzt. Wälder schrumpften. Die Magie zog sich zurück wie ein verwundetes Tier.Wieder handelten Druiden und Barden. Dieses Mal kämpften sie nicht gegen das Vergessen. Sie passten sich an.Die Druiden zogen sich an die letzten Orte zurück, an denen der Glaube noch verweilte – in die tiefen Wälder von Shpresa, unter die Große Goldene Eiche. Sie wurden eher zu Pflegern als zu Führern und hielten das Herz der Welt noch ein wenig länger am Schlagen.Die Barden wandelten ihr Handwerk erneut. Sie sangen weniger offensichtliche Lieder über Magie. Stattdessen sangen sie von Freundschaft, von Mut, von einer Liebe, die über Zeiten und Grenzen hinweg Bestand hatte. Sie vertrauten darauf, dass die Magie sich selbst erkennen würde, wenn der Moment gekommen war.Und das tat sie.Als die letzte Elfe und der letzte Erdwichtel sich zur Ruhe legten, folgte keine Verzweiflung. Es folgte Stille. Eine Stille, die sanft von Druiden behütet wurde, die Wache hielten, und von Barden, die nicht mehr laut sangen – sondern stattdessen demWind ihre Gedanken zuflüsterten.Bis eines Tages, in einer toten magielosen Welt, als die letzte Träne der Eiche mit dem letzten Leben neue Hoffnung gebar, entschieden werden würde ob die Magie und somit das Leben in die Welt zurückkehrten. Und ein neuer Zyklus begann. Doch dies geschah sehr, sehr viel später.Einige sagten, die Magie sei verblasst, weil die Menschheit vergaß. Man sagte, niemand habe versucht, es aufzuhalten.Die Menschen irren sich. Die Welt hat nicht überlebt, weil es Helden gab, deren Taten gepriesen werden. Sie überlebte wegen Helden, die sich entschieden, nicht erkannt zu werden. Und obwohl ihre Namen vergangen sind, summt das Echo ihrer Werke noch immer in Wurzeln und\r\nGeschichten des Windes für Projekt.odt\r\nReimen, an jenen Orten, wo Menschen plötzlich Hoffnung verspüren, ohne zu wissen, woher sie kommt.Die Menschen erinnern sich heute nicht mehr an die Lieder, die Geschichten, die vielen kleinen und großen Taten aus dieser Zeit. An jede Hand, die heilte. An jede Wahrheit, die offengelegt wurde und doch verborgen blieb.Nur der Wind kennt die Wahrheit");
        myTexts.Add("Dritoria war ein Land, in dem die Morgendämmerung verweilte. Jeden Morgen schiendas Sonnenlicht sich nur zögerlich über Hügel und Türme erheben zu wollen, als wünschte sich selbst der Tag, ein wenig länger nachzudenken, bevor er ganz einkehrte. Gelehrte sagten, es liege an dem heiligen Glanz von Dritan, dem Gott des Lichts. Bauern sagten, es liege daran, dass das Land gütig sei. Priester sagten, beides sei wahr. Und vielleicht hatten sie alle recht.In einem kleinen Dorf, nicht weit von den großen Akademien entfernt, lebte ein Mann namens Seren. Er war nicht bedeutend. Er trug keine prunkvollen Gewänder, besaß keine Titel und schrieb keine Bücher, die ihn überdauern würden. Sein Handwerk war das eines Laternenanzünders und Feldhüters – nachts kümmerte er sich um die Öllampen entlang der Straßen, und am Tag half er den Bauern, dem eigensinnigen Boden das Korn abzuringen.Doch Seren besaß eine Gabe. Er hörte zu.Als Seren jung war, studierte er eine Zeit lang an einer der kleineren Schulen. Er lernteBuchstaben, Zahlen, Philosophie und Theologie. Er lernte, wie Gelehrte über die Wahrheit debattierten und wie Priester über die Lehre stritten. Und er lernte noch etwas anderes. Jeder war fest davon überzeugt, im Recht zu sein.Also ging Seren fort. Nicht aus Zorn. Nicht aus Enttäuschung. Einfach, weil er spürte, dass Weisheit, wenn sie wirklich dem Licht angehörte, nicht blenden sollte. Er kehrte auf die Felder zurück.\r\nGeschichten des Windes für Projekt.odt\r\nJeden Morgen erhob sich Seren vor der Dämmerung und stand still da, während sich das erste Licht über das Land ergoss. Er sprach keine Gebete laut aus. Er bat um keineGefälligkeiten. Er erkannte das Licht einfach an und ging dann an die Arbeit.Die Menschen kamen zu ihm, ohne recht zu wissen, warum. Ein junger Priester saß einst bei ihm, geplagt von Zweifeln. Seren stritt nicht über die heiligen Schriften. Er fragte nur: „Macht dein Glaube dich gütiger?“ Ein Gelehrter spottete einst über die Vorstellung von Magie. Seren fragte: „Hört etwas auf, schön zu sein, nur weil man weiß, wie es funktioniert?“ Einem Bauern, der um eine misslungene Ernte trauerte, sagte Seren: „Das Land erinnert sich an Fürsorge. Versuche es noch einmal.“Sie gingen fort und fühlten sich leichter. Sie nannten ihn niemals weise. Nicht mit Worten. Aber alle gingen weiser von ihm, als sie ihm zu Anfang begegnet waren.Als die Jahre vergingen, änderte sich Dritoria. Der Glaube verhärtete sich. Das Wissen wurde scharfkantig. Licht wurde zu etwas, das man eher besitzen wollte, als es zu teilen. Gelehrte taten alles ab, was man nicht messen konnte. Priester wurden misstrauisch gegenüber allem, was nicht in die Lehre passte.Die Magie, die einst still präsent gewesen war, begann zu verblassen. Seren spürte es zuerst. Nicht als Verlust – sondern als Stille. Die Dämmerung kam zwar noch immer, aber sie verweilte nicht mehr.An einem Wintermorgen fand Seren eine Lampe am Wegesrand, die nicht brennen wollte. Egal wie sorgfältig er den Docht stutzte, egal wie rein das Öl war, die Flamme flackerte und erlosch. Er versuchte es erneut. Und erneut. Schließlich umschloss er dieLampe mit seinen Händen und flüsterte – kein Gebet, keinen Zauberspruch – sondern eine Erinnerung.An Wärme. An gemeinsame Mahlzeiten. An Fragen, die ohne Furcht gestellt wurden.Die Flamme hielt stand. Der Wind strich sanft über die Straße und hielt bei ihm inne, wie um zuzusehen.Als der große Konflikt zwischen Glauben und Magie näher rückte, wählte Seren keine Seite. Stattdessen wanderte er. Er trug das Licht von Dorf zu Dorf – manchmal als echte Flamme, manchmal als ein Gespräch, das den Zorn besänftigte, manchmal als eine Frage, die Gewissheiten gerade so weit ins Wanken brachte, dass Mitgefühl Einlass fand. Niemand bemerkte es. Aber dort, wo er gewesen war, wurden weniger Fackeln im Hass erhoben.Eines Abends kehrte Seren nicht nach Hause zurück. Man fand ihn im Morgengrauen am Kreuzweg sitzen, den Rücken gegen einen Grenzstein gelehnt. Eine Lampe stand neben ihm und brannte noch immer. Sein Gesicht war friedvoll.Ein Priester sagte, er sei im Gebet gestorben. Ein Gelehrter sagte, sein Herz habe einfach versagt. Ein Bauer sagte, das Licht habe ihn heimgeholt. Sie begruben ihn in aller Stille. Die Lampe leuchtete eine Weile auf seinem Grab, und verschwand einfach eines Tages.Jahre später schrieben Gelehrte, Dritoria habe die Magie verloren, weil die Menschen dem Aberglauben entwachsen seien. Priester sagten, der Glaube allein habe sie ersetzt. Bauern sagten, das Land habe sich verändert. Ohne zu wissen ob zum Guten oder zum Schlechten.Doch manchmal, in der Morgendämmerung, wenn das Licht nur einen Atemzug länger verweilt als es eigentlich sollte, so schwören manche Reisende, hätten sie eine\r\nGeschichten des Windes für Projekt.odt\r\neinzelne brennende Lampe an einer leeren Kreuzung gesehen. Niemand konnte es sicherklären.Ohne Öl. Ohne Docht. Einfach nur ein Licht.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Agim war niemals ein Land der Könige. Es war ein Land der Häuser. Kriegerfamilien, deren Namen in Stahl und Stein gehauen waren; deren Geschichten nicht gesungen, sondern geschmiedet wurden. Stärke, Disziplin, Meisterschaft – dies waren die Tugenden, die Agim formten. Macht wurde nicht durch Blutvergießen an sich gerissen, sondern durch Ausdauer, Integrität und Weisheit verdient.Unter diesen Häusern war keines bedeutender als das Haus Kareth.Sie waren keine Eroberer. Sie waren Hüter.Das Haus Kareth war vereidigt, ein Gewölbe zu schützen, das tief unter ihrer angestammten Festung vergraben lag. Keine Karte verzeichnete seinen Eingang. KeineInschrift nannte seinen Inhalt. Jede Generation wurde nur das gelehrt, was notwendig war:Bewacht es. Öffnet es niemals. Sprecht zu niemandem darüber.Der Grund dafür war schon lange in den wenigen verbliebenen übertragenen Worten aus der Vergangenheit verloren gegangen.Der letzte Herr des Hauses hieß Ardan Kareth. Er war alles, was Agim bewunderte: ein Meister der Waffen, ein Taktiker ohnegleichen, ein Mann, dessen Wille Eisen bog und dessen Disziplin und Mut niemals wankten. Er glaubte an Meisterschaft über alle Dinge– die Meisterschaft über den Körper, den Geist und die Furcht. Magie, so glaubte er, seinur eine Krücke. Er sagte dies offen. Agim applaudierte.\r\nGeschichten des Windes für Projekt.odt\r\nAls die Welt anfing zu zerbrechen – als sich Gerüchte über Priester und Magier verbreiteten, die im Clinch lagen, über Magie, die schwand und in instabilen Schüben zurückkehrte – kamen Gesandte zu Ardan. Sie sprachen von Artefakten. Von Macht. Von einer Chance, über das Schicksal der Welt zu entscheiden.Ardan wies sie alle ab. „Agim herrscht nicht durch Wunder“, sagte er. „Wir bestehen durch Können.“Doch das Gewölbe unter seinen Füßen regte sich. Zum ersten Mal seit Generationen träumte jemand aus seinem Haus von Feuer. Es war das Feuer einer Schmiede. Ein Feuer, das bereits vielen seiner Ahnen den Weg geleitet und sie durch Visionen und Träume geführt hatte in besonderen Zeiten. Im Traum erschloss ihm das Feuer den Weg hinab an den Ort, den seit Jahrhunderten kein Mensch betreten hatte.Er stieg allein in das Gewölbe hinab. Was er dort fand, war keine Waffe. Es war ein Schwur.Eine Klinge, ja – auf den ersten Blick unscheinbar. Keine Juwelen. Kein Glühen. Nur feingliedrige Runen, die von der Zeit glatt geschliffen waren. Als er sie berührte, überflutete ihn die Wahrheit. Das Haus Kareth war einst mit einer Wahl betraut worden, die niemand sonst zu treffen wagte.Die Klinge war ein Fokus – nicht der Macht, sondern der Entscheidung. Wer auch immer sie führte, der konnte das Gleichgewicht kippen. Wenn die Welt dabei war sich zu spalten in eine Welt mit Magie, und eine in der Magie nicht mehr existierte- dann konnte dieses Artefakt für immer die Welten trennen, oder eine Tür öffnen um sie wieder ganz zusammenzuführen. Die Nutzung der Klinge verlangte die Meisterschaft über das Selbst.Ardan wich zurück.Er erzählte niemandem davon. Agim mobilisierte seine Kräfte. Heere sammelten sich. Der Druck wuchs. Andere Häuser flüsterten, dass Kareth etwas verberge. Dass sie das kommende Zeitalter fürchteten. Und das, was auf den anderen Kontinenten geschah. Ein Wandel stand bevor. Etwas geschah in der Welt... Ardan stand vor dem Spiegel und sah etwas Neues in seinem Spiegelbild: Zweifel. Er hatte alles gemeistert. Alles, außer der Ungewissheit über die Richtigkeit dieser eine Entscheidung.Als der letzte Ruf erschallte – als Agim verlangte, dass er das Geheimnis preisgab, welches sein Haus verbarg, dass er es für sein Land einsetzte –, handelte Ardan. Er riefkeine Armee zusammen.Statttdessen stieg er hinab ins Gewölbe.„Es steht mir nicht zu, über das Schicksal der Welt zu entscheiden.“ Sprach er leise. „Es wäre leicht, die Klinge zu zerbrechen und niemandem mehr diese Wahl zu lassen. Es wäre leicht, diese Klinge für meine persönliche Zwecke einzusetzen. Oder sie der einen oder anderen Seite, den Magiern oder den Priestern, zu überlassen. Es wäre leicht, sich dieser Verantwortung zu entziehen.“Er nahm die Klinge und kniete nieder. „Doch ich werde den Schwur halten.“Er rammte die Klinge in den Stein, erneuerte den Schwur und beschloss, die Gewölbe zu schützen und zu verstärken, sodass niemand Einlass finden konnte. Und einen anderen Weg zu finden mit den Unruhen im Land umzugehen. „Eines Tages...“ sagte ersich „Eines Tages wird jemand kommen, der mit dieser Wahl betraut werden kann.\r\nGeschichten des Windes für Projekt.odt\r\nWenn ich es nicht selber bin, dann wird einer meiner Nachfahren ihm begegnen. Wennmein Haus einen Schwur leistet, so wird dieser gehalten. Und um die Wichtigkeit dieses Schwurs zu untermauern, wird dies der einzige und letzte Schwur sein den meine Familie ablegt.“Mit neugefundener Sicherheit und Kraft schritt Ardan entschlossen durch die Gewölbe. „Wenn wahre Meisterschaft bedeutet, weise zu wählen, dann soll dies Agims größter Sieg sein.“ Niemand würde je erfahren, dass der stolze Krieger in diesem einen Moment seines Lebens Unsicherheit erlebt hatte. Welch schwerwiegende und mutige Entscheidung an diesem Tag getroffen worden war. Und weiterhin würde niemand außer dem Oberhaupt des Hauses Kareth wissen, was wirklich unter der Festung der stolzen Kriegerfamilie verborgen lag.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Zwei Schwestern wurden unter demselben Himmel geboren, zur selben Stunde, als der Wind die Vorhänge des Geburtszimmers bewegte und das Glockenspiel über der Tür zum Klingen brachte. Die Hebammen sagten, die Luft selbst schien den Atem anzuhalten, als die Mädchen zum ersten Mal gemeinsam aufschrien, als hätte die Weltkurzzeitig vergessen, welche Stimme zu wem gehörte.Sie wurden Aerin und Vaela genannt.Von Anfang an glichen sie einander nur in den Dingen, die am wenigsten bedeuteten. Aerin lachte schnell, war unruhig und fühlte sich stets zu weiten Feldern und hohen Orten hingezogen, wo der Wind frei wehte. Vaela war stiller, nachdenklich und zufrieden damit, am Herd oder unter alten Bäumen zu sitzen, Geschichten zu lauschenund zuzusehen, wie der Himmel seine Farben wechselte. Doch obwohl sich ihre Wege früh trennten, band sie etwas Unsichtbares zusammen – etwas, das kein Gelehrter messen und kein Priester ganz erklären konnte.Als sie Kinder waren, sprachen sie oft zur gleichen Zeit und beendeten die Sätze der jeweils anderen, ohne es zu bemerken. Wenn sie getrennt waren, hielten sie plötzlich inne, getroffen von einem Gefühl, das nicht ganz zu ihnen selbst gehörte. Eine plötzliche Wärme in der Brust. Ein scharfer Stich der Sorge. Eine Freude ohne Grund. Sie lernten, ohne dass man es ihnen sagen musste, dass diese Momente der anderen gehörten.\r\nGeschichten des Windes für Projekt.odt\r\nAls die Jahre vergingen, trug das Leben sie in verschiedene Richtungen. Aerin verließ die Heimat, um den alten Straßen zu folgen, Horizonten und halb vergessenen Liedernnachjagend. Vaela blieb zurück, pflegte das Land und die Menschen und wurde zu einer stillen Säule ihres Dorfes. Sie schrieben einander, wenn sie konnten, doch Worte waren nur ein dürftiger Austausch im Vergleich zu dem Wissen, das zwischen ihnen lebte.Ihr schwesterliches Band überbrückte, wie der Wind, jede Entfernung.Aerin schwor, dass jedes Mal, wenn sie lachte, die Brise ihr zu antworten schien, als hätte jemand in der Ferne mit ihr gelacht. Wenn Vaela nachts erwachte, spürte sie manchmal ein Lächeln auf ihren Lippen, ohne jeden Grund – und wusste dann, dass ihre Schwester in Sicherheit war.Als Aerin in einem fernen Land erkrankte, erwachte Vaela mit einem tiefen Schmerz in den Knochen, einer Krankheit, die keinen Namen hatte. Sie saß tagelang am Fenster und lauschte dem Wind, als könnte er Antworten bringen. Und als Aerin genas und schwach über ihr eigenes eigensinniges Überleben lachte, das ihr einige Jahre mehr auf der Welt bescherte, spürte Vaela, wie der Schmerz von ihr wich, noch bevor irgendein Brief eintraf.Doch die Zeit, geduldig und unerbittlich, fordert am Ende das ein was ihr zustand.Es war an einem stillen Morgen, ohne dass ein Sturm oder ein besonderes Ereignis den Moment markierte, als der Tod Aerin zu sich nahm. Es gab keinegroßen Kamp, keinen letzten Schrei – nur einen Atemzug, der sanft ausgestoßen und dem nicht durch ein Einatmen gefolgt wurde. Weit entfernt taumelte Vaela wie von einem Schlag getroffen, ihr Herz machte einen Sprung in ihrer Brust. Sie sank auf die Knie, in der schrecklichen Gewissheit, dass der Welt etwas Unersetzliches genommen worden war. Das Dorf trauerte mit ihr. Man sprach von Verlust und Ende, von der Endgültigkeit des Todes. Vaela hörte zu, aber sie glaubte ihnen nicht ganz.Denn in den Tagen, die folgten, begann sie kleine Dinge zu bemerken. Der Wind verweilte länger als früher. Er legte sich in kalten Nächten um ihre Schultern. Er raschelte genau im richtigen Moment in den Seiten ihrer Bücher. Und manchmal – nur manchmal – hörte sie ein Lachen in der Luft, sanft und vertraut, eher wie ein Echo einer Erinnerung als ein Laut.In Träumen wandelte Aerin an ihrer Seite, nicht länger an Straßen gebunden, oder an Jahre die ihr verblieben. Sie sprach nicht mit Worten, sondern mit Gefühl: Ich bin hier. Ich bin nicht von Dir gegangen.Vaela lebte weiter und wurde älter, wie es alle Sterblichen müssen. Ihr Haar wurde silbern, ihre Hände faltig, aber sie wanderte niemals allein. Wenn sie auf Hügeln oder an offenen Fenstern stand, fand der Wind sie immer. Und als ihre eigene letzte Stunde schlug, lag keine Furcht in ihren Augen.Jene, die bei ihr waren, sagten, der Raum habe sich mit einer sanften Brise gefüllt, warm und hell, obwohl der Tag draußen vollkommen still war. Vaela lächelte, als würdesie jemanden begrüßen, den sie lange erwartet hatte.\r\nGeschichten des Windes für Projekt.odt\r\nSie wurden niemals getrennt. Nicht durch Entfernung. Nicht durch den Tod.Keiner würde jemals wirklich wissen, wie eng das Band dieser geschwisterlichen Liebe geknüpft war.Nur der Wind kennt die Wahrheit");
        myTexts.Add("Lange bevor die Grenzen von Dashuri auf Pergament gezeichnet wurden, bevor Straßen die Wildnis durchschnitten und Hügel sowie Flüsse Namen erhielten, gab es einen Wald, der nur sich selbst gehörte. Die Menschen, die an seinem Rand lebten, nannten ihn das Alte Grün, doch niemand konnte sagen, wie alt er wirklich war. Die Bäume dort wuchsen höher als jeder Turm, ihre Wurzeln wanden sich wie sich langsambewegende Schlangen durch Stein und Erde. Der Wind rührte sich unter ihren Kronen anders – leiser, sanfter – und trug meistens eher Flüstern als Stürme mit sich.In diesem Wald lebte eine junge Hirschkuh, kaum älter als ein Jahr. Sie war schlank und vorsichtig, ihr Fell trug noch die zarte Weichheit der Jugend. Sie hatte die Pfade, die Bäche und die sicheren Lichtungen von ihrer Mutter gelernt, die ihr eine Lektion vor allen anderen beigebracht hatte: Lauf, wenn der Wald dir sagt, dass du laufen sollst.An einem Wintermorgen, als der Frost noch am Moos klebte und die Welt den Atem anhielt, wanderte die Hirschkuh weiter fort, als sie es jemals zuvor gewagt hatte. Der Hunger hatte sie getrieben – der Winter war grausam und Nahrung war knapp. Sie folgte dem Duft von Rinde und Flechten in einen Teil des Waldes, in dem die Bäume\r\nGeschichten des Windes für Projekt.odt\r\nenger zusammenstanden und das Licht zu blassen Fäden dünner wurde. Schnee lag auf den Ästen und rieselte an einigen Stellen still herab.In diesem Moment schrie der Wald auf. Nicht in Tönen, sondern im Gefühl des Tieres.Eine plötzliche Spannung lag in der Luft. Die Vögel verstummten. Der Wind legte sich. Die Hirschkuh erstarrte – doch es war zu spät. Hoch oben in den morschen Kronen gabdas alte Holz nach. Ein gewaltiger Ast, schwer vom Eis und gezeichnet von Jahrzehnten des Verfalls, brach mit einem Donnern los. Er stürzte herab und begrub den Hinterlauf der Hirschkuh unter sich, während er sie gleichzeitig in eine Senke aus gefrorenem Schlamm und Wurzeln drückte.Sie schrie auf, ein Laut, der die Stille wie ein zerbrochener Zweig zerriss. Das schwere Holz drückte sie gnadenlos zu Boden. Jedes Mal, wenn sie versuchte, sich freizukämpfen, grub sich die raue Rinde tiefer in ihr Fleisch, und der gefrorene Boden hielt sie fest wie eine Umklammerung aus Stein. Blut verdunkelte den Schnee unter ihr.Stunden vergingen. Und noch mehr Stunden. Die Kälte begann, ihr Herz zu verlangsamen. Als ihre Kraft zu schwinden begann, bemerkte sie eine Bewegung in der Nähe – tief am Boden, flink und zielstrebig.Eine Füchsin tauchte zwischen den Wurzeln einer uralten Eiche auf. Sie war älter, ihr Fell um die Schnauze grau bestäubt, ein Auge von einer alten Wunde getrübt. Füchse waren für ihre Klugheit bekannt, nicht für ihren Mut, und schon gar nicht dafür, sich leidenden Geschöpfen zu nähern, die unter der Last des Waldes gefangen waren. Dennwo ein verwundetes Tier lag, da waren oft die Jäger des Waldes nicht fern.Doch diese Füchsin floh nicht. Sie umkreiste die Hirschkuh langsam, prüfte den liegenden Stamm und ließ die Ohren bei jedem fernen Geräusch zucken. Die Hirschkuherwartete Zähne – schmerzhaft, barmherzig, endgültig. Stattdessen setzte sich die Füchsin hin. Sie studierte den Stamm und die Senke lange Zeit, den Kopf mal zur einen, mal zur anderen Seite neigend, alshörte sie nicht nur auf das Knacken des Holzes, sondern auf den Wald selbst.Dann handelte sie. Mit sorgfältiger Präzision begann die Füchsin, die gefrorene Erde unter dem Lauf der Hirschkuh wegzugraben. Dort, wo der Körper der Hirschkuh dem Boden bereits etwas seiner Wärme gespendet hatte. Ihre Krallen bluteten, als der harte Boden ihr Widerstand leistete, doch sie hielt nicht inne. Sie biss in störende Wurzeln und zerrte Erde mit ihren Pfoten beiseite, um den Hohlraum unter dem schweren Ast zu vergrößern.Es dauerte Stunden. Die Hirschkuh verlor einmal, vielleicht zweimal das Bewusstsein. Als sie erwachte, war der lähmende Druck gewichen. Die Füchsin hatte tief genug gegraben, dass das Bein der Hirschkuh aus der tödlichen Falle in den freigelegten Tunnel rutschen konnte.\r\nGeschichten des Windes für Projekt.odt\r\nDie Hirschkuh brach zusammen, ihr Bein verwundet, aber frei. Die Füchsin drückte ihreNase kurz gegen die Flanke der Hirschkuh – eine stille Geste, ein Abschied und ein Versprechen – und verschwand im Unterholz.Die Hirschkuh überlebte. Die Wunde heilte langsam und hinterließ eine Narbe sowie ein leichtes Hinken, das nie ganz verschwand. Sie trug es für den Rest ihres Lebens, eine stille, in das Fleisch geätzte Erinnerung. Jahre vergingen. Das Alte Grün veränderte sich, wie Wälder es tun. Bäume fielen und wuchsen neu. Bäche verlagertenihren Lauf. Die Hirschkuh wurde älter, weiser und schließlich selbst Mutter. Sie zog ihreKitze in den tieferen Teilen des Waldes auf und lehrte sie, auf den Wind zu hören.Eines Frühlings, als die Welt wieder grün geworden war, spürte die Hirschkuh die Gefahr, lange bevor sie sie sah. Die Wölfe waren zurückgekehrt. Ein Rudel – jung, hungrig, verzweifelt. Sie roch sie in der Luft, und Panik stieg in ihr auf. Ihre Kitze zerstreuten sich, wie sie es gelehrt hatte, doch nicht alle waren schnell genug. Die Wölfe kesselten sie ein. Die Hirschkuh rannte und lockte sie fort, ihr verletztes Bein brannte bei jedem Schritt. Sie wusste, dass sie ihnen nicht ewig entkommen konnte. Gerade als ihre Kraft nachließ, veränderte sich der Wald. Aus den Schatten kam Bewegung – flink, koordiniert, zielgerichtet.Füchse. Nicht einer, sondern viele. Ein ganzes Rudel, ihre roten Pelze blitzten zwischenWurzeln und Farnen auf. Sie stürzten sich auf die Wölfe, bissen in ihre Fersen, verschwanden und tauchten anderswo wieder auf, verwirrten und spalteten das Rudel.Der Wald selbst schien ihnen zu helfen; Äste verfingen sich im Fell der Jäger, unebenerBoden wandte sich gegen sie.An ihrer Spitze stand eine alte Füchsin mit einem getrübten Auge.Die Wölfe, desorientiert und frustriert, zogen sich schließlich zurück, vertrieben nicht durch Stärke, sondern durch Beharrlichkeit und List. Die Hirschkuh stand zitternd da, ihr Atem ging stoßweise. Die Füchsin näherte sich ihr langsam. Sie betrachteten einander für einen langen Moment – zwei Leben, verbunden durch eine Vergangenheit,über die keine von beiden sprechen konnte. Dann wandte sich die Füchsin ab und führte ihr Rudel zurück in die grünen Tiefen. Die Kitze der Hirschkuh tauchten unversehrt aus dem Dickicht auf.Die Jahreszeiten wechselten. Jahre später, lange nachdem die Hirschkuh verstorben und ihre Knochen zur Erde zurückgekehrt waren, hielt eine junge Wölfin Wache über einen Wurf Welpen am Waldrand. Einer der Welpen wanderte zu weit fort und purzelte auf eine verborgene Schlucht zu. Eine Füchsin – alt, grau und müde – schoss hervor, packte den Welpen im Nacken und zerrte ihn in Sicherheit, bevor sie verschwand, nochehe die Wölfin reagieren konnte.Die Wölfin wusste nie, warum die Füchsin so gehandelt hatte. Sie wusste nur, dass der Wald ihr Kind beschützt hatte. Und so wurde die Gunst des Alten Grüns über die Füchse an alle Tiere weitergegeben – eine tiefe Erinnerung, ein tiefliegender Instinkt, eingewoben in das lebendige Gefüge des Alten Grüns.\r\nGeschichten des Windes für Projekt.odt\r\nDie Menschen, die in der Nähe lebten, sagten manchmal, der Wald habe eine Seele. Sie hatten nicht unrecht. Und davon, dass es Glück brachte einen Fuchs zu erspähen. Man munkelt sogar, dass eine besonders gutmütige, ergebene und weise Füchsin dem Alten Grün als Waldgeist diente. Und wenn der Wind sanft durch die Bäume weht und den Duft von Moos und Erde trägt, flüstert er von Freundlichkeit, die ohne Erwartung gegeben und weiter getragen wird, über Generationen hinweg.Kein Mensch wusste sicher, was im Alten Grün vor sich ging.Nur der Wind kennt die Wahrheit.");
        myTexts.Add("Die drei Freund Yuki, Abed und Lal lebten im kleinen aber idyllischen Dorf Miko, an der Grenze des Lande Okoku im Kontinent Dritoria. Ihr Zuhause befand sich genau zwischen dem Waldgebiet und der Wüste.Neben ihren Familien, gab es einige weitere Personen im Dorf die sie besonders liebgewonnen hatten: den freundlichen Händler Laros, der immer eine Süßigkeit bereithielt wenn die Kinder für ihre Eltern einkaufen gingen, den alten Fischer Taman, der nach einem ereignisreichen Leben auf See in seine alte Heimat zurück gekehrt war und immer spannende und lehrreiche Geschichten auf Lager hatte, wenn die Kinder sich beim Fischen zu ihm setzten...Aber ganz besonders liebten sie Sofu. Alle im Dorf zeigten ihm großen Respekt und erzählten den Kindern, dass er es gewesen war, der Miko zu einem solch florierenden Ort gemacht hatte, der zugleich trotz seiner Popularität nichts an Idylle einbußen musste. Sofu liebte alle Kinder, und er hatte Yuki, Abed und Lal besonders ins Herz geschlossen.Er saß bei ihnen wenn sie spielten, und erzählte ihnen Geschichten über ferne Länder, voller Magie. Besonders gern erzählte er ihnen von Shpresa, und den wundersamen Gesängen der Barden, deren Meistern man nachsagte sie hüteten die Geheimnisse der\r\nGeschichten des Windes für Projekt.odt\r\nWelt. Viele Legenden rankten sich um die wahre Macht der Barden. Man sagt, wer es schafft das Vertrauen eines Barden zu gewinnen, der kann nur reinen Herzen sein. Denn ihr weiser Blick schaut direkt in die Seele.Eine der Geschichten die sie hörten war direkt mit dem Dorf Miko verbunden. Der geheimnisvolle Sturm, der alle 13 jahre durch die Wüste fegte und die dortige Karawanenstraße eine Zeitlang unpassierbar machte, würde bald wieder die Straßen unbenutzbar machen und jede Reise hinein in die Wüste sehr gefährlich. Aber natürlich nur für die, die nicht wussten worauf man achten musste um sich zu schützen... Die drei Freunde berieten sich, denn sie hatten gehört, dass der Sturm einst von einem bösen Magier verursacht worden war, der von den mutigen Priestern Dritas für immer in seinen Hexenturm verbannt worden war. Und dieser Turm erschien nur zur Zeit des Sturms... Vielleicht konnten sie den Turm des Magiers finden und große Helden werden, wie die aus den großen Geschichten und Legenden! Der Sturm würde bestimmt langsam beginnen, und es war bestimmt zumindest für einige Tage nicht zu gefährlich, danach zu suchen...Ich möchte ein großer Held sein!“ rief Yuki und hob heroisch ihr Holzschwert. Abed warnte: „Aber Mama hat gesagt, wir dürfen nicht mehr so weit in die Wüste zum Spielen. Es ist gefährlich“. Lal fragte: „Bist Du sicher, dass Du den Turm suchen möchtest?“. Yuki antwortete, ohne Zögern und ohne Angst: „Ja“. „Na gut“, sagte Lal. „Wie wäre es als Kompromiss, wenn wir in der Nähe von meinem Zuhause Ausschau halten, und uns in Sicherheit bringen, sobald wir den Sturm sehen? Wir können eine kleine Suchexpedition machen, den Ausguck nutzen, und wenn es brenzlig wird, laufen wir einfach zu mir nach Hause. Wäre das in Ordnung?“. Abed nickte schüchtern, aber er wirkte zufrieden.„Hey! Kommt schon! Etwas mehr Begeisterung!“ rief Yuki. „Das wird unser größtes Abenteuer!“. Lachend umarmte sie ihre Freunde und hielt ihre Faust in die Mitte. „Wenn wir immer füreinander da sind, dann kann uns niemals etwas Schlimmes passieren.“ Sie strahlte ihre Freunde an. „Freunde für immer!“. Lal lachte und legte die linke Hand auf Yukis Faust: „Freunde für immer!“Abed lächelte und wirkte nicht mehr so besorgt. „Freunde für immer“, sprach er und legte seine rechte Hand auf Lals.Gerade als sie auf den höchsten Felsen geklettert waren, den sie in diesem Gebiet kannten, und immer noch nichts am Himmel zu sehen war, wollten sie schon aufgeben: Da rief Abed: „Seht doch, was ist das für ein seltsames Leuchten?“. Und tatsächlich: Weit entfernt, gerade so mit dem Fernrohr sichtbar, inmitten eines flimmernden Lichts, war der dunkle Umriss eines Turms zu erkennen. Lal bestätigte, dass er und Vater Vaelin schon oft in der Gegend unterwegs gewesen waren, aber dasssie den Turm noch nie gesehen hatten. Aufgeregt schauten die drei einander an. „Wenn wir dorthin laufen, dann sind wir erst am Morgen wieder zurück. Papa Vaelin wird wütend sein“, überlegte Lal. Yuki hingegen platzte fast vor Tatendrang: „Worauf warten wir dann noch? Denkt Ihr, die großen Helden konnten ihre Abenteuer bestehen, weil sie immer pünktlich zum\r\nGeschichten des Windes für Projekt.odt\r\nAbendessen zuhause waren?“. Und so war es beschlossen. Die drei Freunde konnten sich diese unglaubliche Entdeckung nicht entgehen lassen. Sie liefen zum Turm.Angekommen am Turm verspürten die drei Freunde einen kalten Schauer, der ihnen den Rücken hinunterlief. „Kommt schon der Sturm?“ fragte Abed ängstlich. „Nein“, antwortete Lal und schaute sich um. „Der Himmel ist klar“. „Es muss die böse Magie des Hexenmeisters sein“, behauptete Yuki entschlossen. Es war eine unheimliche Kraft, zugleich wie ein Sog, der an ihnen zerrte, und wie eine unsichtbare Wand, die sie mühsam vor sich herschieben mussten, um voranzukommen. „Es heißt in einigen Geschichten,die Priester Dritans hätten den bösen Magier eingesperrt. Wenn er das wirklich ist, dann sollte uns keine Gefahr drohen“, sagte Lal. Die schwere Holztür erschien zunächst wie ein unüberwindliches Hindernis, bis Lal in den Türspalt spähte und feststellte, dass sie nicht verschlossen war. Sie gingen hinein. Als sie eintraten, blieben ihre Herzen vor Schreck stehen und vergaßen zu schlagen. Da stand er: Der Meistermagier. In einem Runenkreis, der magisch aufleuchtete. „Etwas stimmt nicht“, flüsterte Abed. „Er sieht nicht so aus, als wäre er eingesperrt!“. Erschrocken lief er zur Seite, um sich hinter einer Kiste zu verstecken. Lal hatte sich bereits hinter einer Säule verborgen. Nur Yuki blieb trotz ihrer Angst dickköpfig stehen und legte die Hand auf ihr Holzschwert.Abed stolperte, und fiel gegen ein Regal, das umkippte. Ein Krug zerbrach und sein Inhalt ergoss sich über die Zeichen des Kreises. Der Magier zauberte hektisch weiter und rief laut: „KAZAAHM! KAZAAHM!“. Yuki hörte, wie Lal irgendetwas rief und loslief. Sie konnte es aber nicht verstehen, ergriff aber Abeds Hand und lief mit ihm hinaus. Der Turm stürzte hinter ihnen zusammen.Yuki erwachte in ihrem Bett. Sie war verwandelt. Einige Stellen an ihrem Körper waren mit seltsamen Tiermerkmalen versehenSie erfuhr, dass der Sturm vorüber war, und dass die Überreste eines toten Kindes in der Wüste gefunden worden waren. Viele lange Jahre lang lebte sie mit der Schuld, den Tod ihrer beiden Freunde verursacht zu haben. Auch wenn sie durch das Trauma des Erlebnisses nicht mehr wusste, was geschehen war. Und doch ließ sie niemals das Gefühl los, dass sie nicht ganz verloren waren. Nach 13 Jahren betrat sie wieder den Turm, erinnerte sich daran dass sie damals den Magier bei einem Ritual gestört hatten,und dass etwas schiefgelaufen war- und entdeckte das Tagebuch das Magiers. Die Zeitschien hier im Turm anders zu verlaufen. Was er schrieb gab ihr zu denken und machtesie neugierig.Nach langen Reisen, die Yuki durch alle drei Kontinente führten, und vielen Gesprächenin denen Sofu ihr guten Rat gab, kehrte Yuki nach hause zurück. Sie musste das Geheimnis des Turmes endgültig lüften, und ihre Freunde retten. Es musste einen Weg geben. In ihrem Herzen konnte sie spüren, dass sie noch nicht verloren waren.Auf ihren Reisen erfuhr sie von der Spaltung der Welt. Dass der Klerus versuchte den magischen Teil der Welt für immer abzuspalten. Während die Magier versuchten, dies zu verhindern. Einer der fanatischsten Diener Dritans verfolgte sie. Als Yuki den\r\nGeschichten des Windes für Projekt.odt\r\nMeistermagier im Turm aus seinem Gefängnis befreite, das sie und ihre Freunde damals mit ihrem Missgeschick selber kreiert hatten, um zu erfahren was mit ihren Freunden geschehen war, kam es zu einem Mampf zwischen dem Magier und dem Priester, der nun zur Tür eintrat.Das Geschenk eines weisen alten Kriegers aus Agim, ein mächtiges Artefakt, war dazu in der Lage über das Schicksal der Welt zu entscheiden. Er hatte es ihr anvertraut, in dem Wissen dass sie gerade dabei war die Wahrheit der Geschichte der Kontinente zu ergründen. Und weil sie als Mensch geboren, aber auch von Magie gezeichnet war, überließ er ihr das Artefakt und somit die Entscheidung über das Schicksal der Welt.Doch viel wichtiger: Yuki verstand, dass sie ihre Freunde retten konnte.Yuki wollte nicht zulassen, dass die Magie aus der Welt verschwand, und halfdem Magier. Beide Gegner-Magier und Priester- erschlugen einander gegenseitig. Und der Priester versuchte auch, Yuki zu töten. Doch Sofu warf sich zwischen die beiden. Erkennend, dass Sofu, der überraschend auftauchte und sich opferte um sie zuretten, in Wahrheit Lal war, brach Yuki in Tränen zusammen.Bevor er für immer seine Augen schloss, flüsterte Sofu „Es war so schwer... Ich wollte es Euch so gerne sagen... Wollte Euch warnen. Aber dann wäre all das Gute nicht passiert... Ich habe so viel für unser Dorf erreicht. Konnte so vielen Menschen helfen... Das konnte ich ihnen nicht antun. Ich durfte dies nicht rückgängig machen, durfte ihnen das alles nicht nehmen.“ Tränen standen in seinen alten Augen.„Ich weiß, Du kannst Abed retten. Keinem von uns muss etwas Schlimmes passieren. Ich weiß Du spürst es auch. Tief im Innern. Wir sind füreinander da.“ Er legte seine Hand auf ihre. „Freunde...“ bevor er den Satz vollenden konnte, verließ ihn seine Kraft.Er entließ das Wort mit seinem letzten Atemhauch.„Freunde für immer...“ Flüsterte Yuki, kaum hörbar, mit erstickter Stimme, und legte ihm die Hände auf die Brust.Wenn Lal durch den magischen Unfall damals in der Zeit zurück geworfen worden war,dann musste es doch auch möglich sein Abed zu erreichen.... Oder?Nicht wissend, ob es sie ihr Leben kosten konnte und ob sie lieber aus dem Turm fliehen sollte, näherte sich Yuki ein letztes Mal dem magischen Ritualkreis, an dem damals alles begonnen hatte. Sie konnte in einer Vision, einer Art magischem Fenster zusehen wie die Ereignisse ihrer Vergangenheit ein letztes Mal abliefen: wie der Magierund Lal im Zeitzauber gefangen und mitgerissen wurden- und als Abed hinauslief, zur kleinen Yuki von damals, um ihre Hand zu ergreifen, da streckte die erwachsene Yuki einem Impuls folgend ihre Hand aus. Teils von einem Instinkt geleitet der ihr seit jenem Tag innewohnte, teils aus Sehnsucht nach ihrem lieben Freund den sie verloren hatte. Sie ergriff den jungen Abed, zog ihn zu sich, und ein letztes Mal- liefen Yuki und Abed hinaus aus den Ruinen des Turm, dessen Ruine nun endgültig hinter ihnen zusammen stürzte.In Miko angekommen, schlief Abed mehrere Tage. Yuki nahm ihn bei sich auf, als ihr eigenes Kind. Er konnte sich -wie sie selber damals- nach seinem Erwachen an nichts erinnern, und lebte ein langes und glückliches Leben.\r\nGeschichten des Windes für Projekt.odt\r\nDrei Kinder aus dem kleinen Dorf Miko hatten ein Band der Freundschaft geknüpft, dasstärker war als Raum und Zeit. Sie ließen einander nicht im Stich, und jedes der Kinderwuchs auf und lebte ein langes und erfülltes Leben. Zwei von ihnen nahmen das Geheimnis mit ins Grab, dass sie dieses Leben zu unterschiedlichen Zeiten führten. Und doch wurden ihre Leben voneinander berührt. Drei Kinder, drei Generationen.Kein Mensch würde jemals davon erfahren. Und kein Mensch würde jemals wirklich wissen, wie die Magie in die Welt zurück gekehrt war.Denn die Wahrheit kennt nur der Wind...");
        myTexts.Add("Vor langer Zeit, in einer Welt namens Dashuri, hatte der Kreis des Lebens seinen Endpunkt erreicht. Wie schon einige male zuvor, endete das Zeitalter der Magie. Ein Wendepunkt nahte. Denn mit dem Zeitalter der Magie endete auch das Leben in der Welt. Würde dies der endgültige Abschluss sein? Würde nach diesem Kreislauf des Lebens die Welt wirklich sterben, und nur noch von Geistern und deren Erinnerungen beseelt sein?Voller Liebe, Glück und Wehmut fiel mit der Träne der Großen Goldenen Eiche auch ihre letztes Stück Lebenskraft hinunter. Der letzte Tropfen Magie.Die letzte Hoffnung für die Welt, wenn sie wieder mit Leben erweckt werden wollte. Viel Zeit verging, bis die Welt ohne Magie endgültig allmählich starb. Es gab kein Leben mehr in ihr. Außer an einem einzigen Ort. An einer winzigen Stelle, die noch ein letztes Mal Leben erschaffen konnte.Ein kleines unschuldiges Baumwesen formte sich aus der Träne. Es wusste nicht wer es war, und warum es hier war. Doch es spürte Liebe, Glück und Wehmut in seinem Herzen. Und Neugier. Es wusste, dass es mehr herausfinden würde über seine Herkunft und seine Aufgabe in der Welt, wenn es nur lange genug suchen würde.Auf seiner Reise begegneten ihm kleine Lichter. Es waren die Geister von Tieren. Die kleinsten waren Glühwürmchengeister, die nach ihrem Tod zum Irrlicht wurden. Aber das kleine Wesen konnte ihre wahre Gestalt erkennen. Auch andere Tiere, die noch nicht wie einige Geister verdorben worden waren, halfen dem kleinen Wesen seine Reise sicher und gut fortzusetzen. Sie verliehen ihm einige der Fähigkeiten, die den Tieren selber einst im Leben zur Verfügung gestanden hatten. Die erste gute Seele die dem kleinen Wesen begegnete, gehörte einem Hasen. Freudig sprühte das kleine Wesen nun voller Energie und Sprungkraft, und schaffte es, weiter zu springen als jemals zvor.Den dunklen Geistern aber musste es ausweichen. Sie waren so traurig, oder wütend, oder verängstigt weil die Magie aus der Welt verschwunden war, und dass es kein Leben mehr gab in der Welt, dass sie dem kleinen Wesen weh taten. Es war scheinbar das einzige in dieser Welt, das noch wirklich lebte. Die dunklen Geister waren bestimmt neidisch. Das kleine Wesen wollte ihnen nicht weh tun. Aber wenn es sein Licht auf sie warf, dann wurden sie aus irgendeinem Grund friedlich für eine kurze Zeit. Das würde es sich merken.Das kleine Wesen war gespannt, was es noch in der Welt zu entdecken gab. Und ob es herausfinden würde, wie und warum es in die Welt gekommen war.");
        myTexts.Add("Das kleine Wesen überwand viele Gefahren. Es war eine große, und düstere Welt. Aber sie war auch schön, auf ihre ganz besondere geisterhafte Art. Je länger das kleineWesen durch die Welt reiste, desto mehr hatte es das Gefühl, diese Welt zu kennen. Und es spürte, dass auch die Welt sich an etwas erinnerte. Jedesmal, wenn es über den Boden lief; wenn es über einen Stein hüpfte. Jedesmal, wenn es ein wenig Licht in die Dunkelheit zauberte, erschien es ihm, als würde eine Erinnerung geweckt. „Wenn ich einfach immer weiter gehe,“ dachte das kleine Wesen „, dann werde ich mich bestimmt auch selber erinnern- daran wer ich bin!“Frohen Mutes betrat es selbst die dunkelsten Orte.\r\nGeschichten des Windes für Projekt.odt\r\nAm Waldrand wurden die Dornenhecken immer dichter. Aber es erspähte den Eingang zu einer Höhle. Mutig trat es ein, gespannt wohin die Tunnel es führen würden. Es war bereits der Seele eines Hasen begegnet. Und vorhin im Wald auch der Seele eines Vogels. Es hatte so viel Spaß gemacht über den Boden zu gleiten! Schwerelos, schwebend.Doch alles Schweben nutzte ihm nichts in dieser völligen Dunkelheit... Da blitzten zweiAugen auf. Furchtlos näherte sich das kleine Wesen. Die Seele einer Katze schnurrte und schenkte dem kleinen Wesen ihre Augen und Ohren. Es konnte spüren, dass die Katze ihm eine gute Reise wünschte.Auf einmal war alles so hell! Das kleine Wesen blinzelte zum ersten Mal in seinem Leben. Doch es öffnete langsam wieder die Augen. Denn ein lautes Tropfen ertönte. War das Geräusch schon vorher da gewesen? Dies war erstaunlich! Überwältigt von den neuen, intensiven Sinneseindrücken durchquerte es vorsichtig die Tunnel. Es musste aufpassen! An vielen Stellen konnte es sich schneiden, oder hinunterfallen in die Tiefe. Zwar gab es hier keine bösen Geister, aber dieser Untergrund barg seine ganz eigenen Gefahren.Aber selbst hier fand es die Geschichten des Windes. Auf seinem gesamten Weg erfreute es sich daran, wie viel der Wind ihm von der Welt erzählen konnte. Der Wind, dankbar einen Zuhörer zu haben der ihn verstand, flüsterte ihm zahlreiche Geschichten aus der Welt zu. Aus allen Ländern und allen Zeiten. Es war, als wäre das kleine Wesen selber die Welt, und könnte zusehen und erleben, wie diese wunderbaren Geschichten sich abspielten.So schade, dass niemand außer dem Wind sich daran erinnern konnte und wusste, waswirklich geschehen war. Die Welt war ein wahrer Reichtum an Schätzen in Form von Geschichten, wenn sie mit Leben gefüllt war");
        myTexts.Add("Es war nicht mehr kalt. Das kleine Wesen spürte, als es wieder die Oberfläche erreichte, im Gegenteil die heiße Sonne auf sich brennen. Nach all der Kälte und Finsternis freute es sich sich über so viel Licht. Selbst im Wald hatte es die Sonne nichtso deutlich am Himmel sehen können. Nur einzelne Lichtstrahlen waren durch die Baumkronen gefallen.Das kleine Wesen konnte spüren, dass trotz der Leere an diesem Ort einst jemand gelebt haben musste. Es fragte sich, wie lange das wohl her sein mochte? Es gab Steine, und Säulen, und seltsame Tafeln und Figuren mit Zeichen darauf. Es sind Runen, dachte es bei sich. Ohne zu verstehen, woher dieses Wissen kam.Auf einmal erschienen neue Geister. Ein altes Skelett lag vor dem kleinen Wesen. Ein Teil der verdorbenen Seele schien sich noch daran zu erinnern, wie das Tier einst zu Lebzeiten ausgesehen hatte. „Ich muss aufpassen“, dachte das kleine Wesen. „Das sind wieder dunkle Geister. Ich sollte ihnen aus dem Weg gehen.“\r\nGeschichten des Windes für Projekt.odt\r\nUnterwegs traf es die Seele eines lustigen Tieres, das ihm die Fertigkeit gab sich zusammenzurollen und kräftig und fast unaufhaltsam nach vorne zu rasen. Das war eine große Hilfe! So konnte es manche Mauern zerbrechen und viele Geheimnisse der Welt besser entdecken, und auch besser manche Gefahren umgehen. Außerdem konnte ihm niemand weh tun, solange es nach vorne rollte. Aber dem kleinen Wesen wurde jedesmal furchtbar schwindelig, wenn es das tat. „Ich sollte das nicht zu oft tun.Ich mache besser jedesmal danach eine kleine Pause.“ Dachte es bei sich.Auf Wandbildern konnte das kleine Wesen drei Säulen sehen, auf denen wieder Runen eingemeißelt waren. Drei davon leuchteten „Ich sollte mir das merken“, dachte es. „Wer weiß, das könnte noch wichtig werden.“Es stand vor einem hohen Berg. Da es neugierig war und keine Angst haben musste vorm Herunterfallen, kletterte es hoch. Der Wind fegte nach links und nach rechts, unddas kleine Wesen jubelte und lachte, als es durch die Gegend flog. Wenn es den Moment richtig abpasste, dann konnte es sich vom Wind und von den Flügeln der Vogelseele weit tragen lassen.Auf einmal war das Ende erreicht.Das kleine Wesen kam auf einen großen Platz. Es erkannte die drei Säulen mit den Runen, und berührte sie. Es spürte, dass ihm eine Energie innewohnte, die die Runen zum Leben erwachen ließ.Magie floß vom kleinen Wesen in die Runen hinein und wurde tausendfach verstärkt. „Dies ist so aufregend!“ Dachte das kleine Wesen erfreut. Noch nicht ahnend, dass daswahrhaft Aufregende ihm noch bevorstand.Der Steinhaufen, der hinter den Säulen in einem Ritualkreis lag, formte sich zusammen zu einem riesigen Ungeheuer aus Stein!Dem Stampfen und den Schlägen ausweichend, versuchte das kleine Wesen auf die andere Seite zu rennen. Es vermochte dem Steinmonster auszuweichen, und lief instinktiv zu dem Runenstein der hinter ihm lag. Als es die Rune berührte, legte sich der Wächter wieder schlafen.Das kleine Wesen überlegte gerade, ob es fortfahren sollte- doch da erblickte es schimmernde Platformen in der Luft! Ein Weg schien sich zu formen.Als es die Runen mit den schimmernden Platformen eine Treppe nach oben formten, begann das kleine Wesen mehr und mehr zu verstehen, dass es durch Magie geboren war. „Ich bin magisch, wie dieses Steinwesen“, dachte es. „Deshalb konnte ich den Runen von meiner Magie geben.“ Ein Bewusstsein regte sich in ihm, als es empor klomm.„Ich weiß nun, was meine Bestimmung ist.“ Sprach es, als es die letzte Seele auf seiner Reise berührte. Es war die eines Phönix.");
        myTexts.Add("Es hatte ihn nun, nach seinem Tod, aus seinem Gefängnis befreit.Der Phönix war ein besonderes Tier. „Du bist magisch, wie ich!“ sprach das kleine Wesen, als es sich als Phönix emporhob und wieder zum Wald zurück flog. Zurück zur Großen Goldenen Eiche.„Ja.“, antwortete ihm der Phönix, der das kleine Wesen in sich trug, und ihm zugleich erlaubte seine Form anzunehmen. „Wir sind beide Wesen der Magie. Ich habe Dich bereits erwartet. Wenn Du es möchtest, dann kannst Du die Magie in die Welt zurück bringen. Und das Leben. Möchtest Du das?“ Fragte der Phönix, während sie beide gemeinsam Windböen auswichen, und versuchten nicht die dunklen Geister des Waldes zu berühren, die bereits das nahende Ende ihres Fluges ankündigten.„Ja.“ Sprach das kleine Wesen.„Du möchtest das, wissend was der Preis dafür ist?“ Fragte der Phönix wieder.„Ja.“ Antwortete das kleine Wesen, ohne zu zögern. „Das möchte ich. Es ist meine Aufgabe. Ich möchte sie erfüllen, damit mein Leben einen Zweck hat.“„So soll es sein.“ Sagte der Phönix als sie landeten. „Somit verleihe ich Dir als Abschiedsgeschenk meine Kraft. Wenn ein Leben endet, dann kann ein neues Leben beginnen.“Das kleine Wesen war wieder es selber. Es fühlte immer noch die Kraft und das Feuer des Phönix in seinem kleinen grünen Körper. „Wenn ein Leben endet, dann kann ein neues beginnen.“ Sprach es. Während es den Baum hochkletterte, wurde es vom Wind umweht, der es begleitete. Es wollte den Wind gerne noch etwas fragen, aber es machte zu viel Spaß auf den Blättern und Zweigen zu hüpfen. Und es musste aufpassen, dass es nicht die dunklen Geister berührte falls diese erschienen. Doch sie waren nicht zu sehen.\r\nGeschichten des Windes für Projekt.odt\r\nSchließlich war es im toten Herzen der Großen Goldenen Eiche angekommen. Das kleine Wesen legte sich hin, und ließ die Magie, die es zum Leben erweckt hatte, langsam in das Herz der Eiche zurück fließen. Während das kleine Wesen die Augen schloss, und langsam in den ewigen Schlaf glitt, flüsterte es dem Wind zu. „Wirst Du Dich auch an meine Geschichte erinnern?“ Doch bevor es eine Antwort erhalten konnte, schlug sein kleines gutes Herz zum letzten Mal.In dem Moment, in dem das Leben aus dem kleinen Wesen hinaus floß, sickerte die Magie wie flüssiges schimmerndes Gold in das Herz der Großen Eiche hinein. Sie erwachte wieder zum Leben.Als ihr großes goldenes Herz wieder begann mit neuer Kraft zu schlagen, weil die Erinnerung an die Magie durch ein großes Opfer in die Welt zurück getragen worden war, begann auch die Welt wieder zu neuem Leben zu erwachen. Langsam und stetig beruhigten sich die verdorbenen Seelen in der Welt, und fanden Frieden.Neue Pflanzen wuchsen. Und mit den ersten erwachenden magischen Wesen kehrten auch diejenigen Wesen in die Welt zurück, die neue Tiere erschaffen konnten.„Dieser Teil des Waldes ist besonders schön.“ Sprach ein kleiner Waldgeist. Er war einer der Erdgeister, die in der Erde wohnten.„Ja. Lass ihn uns ‚das Alte Grün‘ nennen. Denn ich glaube, es wird hier eine lange Zeit so schön grün sein.“ Sagte seine Freundin.Der Erdwichtel und die kleine Elfe machten sich auf den Weg. Sie hatten viel zu tun. Aber sie hatten keine Eile. Schließlich hatten sie ja alle Zeit der Welt.„Wie hat das alles eigentlich angefangen?“ Fragten sich Feen, Tiere, Menschen und viele andere Wesen auf der Welt irgendwann. „Woher kommt die Magie?“ „Wird das hier für immer so sein? Oder muss es irgendwann enden?“Diese Fragen, so wie viele andere, würden für immer unbeantwortet bleiben.Denn die Wahrheit kennt nur der Wind.");

    }

    public void OpenStoryPanel(int index)
    {
        myLoadMenu.ClickSoundPlayNoDeactivation();
        storyPanel.SetActive(true);
        collectionPanel.SetActive(false);
        storyImage.GetComponent<Image>().sprite = myButtons[index].GetComponent<Image>().sprite;
        caption.GetComponent<TMP_Text>().text = myCaptions[index].ToString();
        storyText.GetComponent<TMP_Text>().text = myTexts[index].ToString();
    }
}
